sealed class FfiBknException: kotlin.Exception() {

    class Backend(

        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "message=${ `message` }"
    }

    class TableNotFound(

        val `table`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "table=${ `table` }"
    }

    class NotFound(
        ) : FfiBknException() {
        override val message
            get() = ""
    }

    class Encoding(

        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "message=${ `message` }"
    }

    class ReservedTableName(

        val `table`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "table=${ `table` }"
    }

    class DatabaseLocked(

        val `path`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "path=${ `path` }"
    }

    class DuplicateKey(

        val `table`: kotlin.String, 

        val `key`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "table=${ `table` }, key=${ `key` }"
    }

    class SchemaMismatch(

        val `table`: kotlin.String, 

        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "table=${ `table` }, message=${ `message` }"
    }

    class ConstraintViolation(

        val `table`: kotlin.String, 

        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "table=${ `table` }, message=${ `message` }"
    }

    class Corruption(

        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "message=${ `message` }"
    }

    class InvalidQuery(

        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "message=${ `message` }"
    }

    class DatabaseClosed(
        ) : FfiBknException() {
        override val message
            get() = ""
    }

    class TransactionInProgress(
        ) : FfiBknException() {
        override val message
            get() = ""
    }

    class TransactionClosed(
        ) : FfiBknException() {
        override val message
            get() = ""
    }

    class TransactionAborted(

        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "message=${ `message` }"
    }

    class InvalidArgument(

        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "message=${ `message` }"
    }





    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiBknException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiBknException = FfiConverterTypeFfiBknError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeFfiBknError : FfiConverterRustBuffer<FfiBknException> {
    override fun read(buf: ByteBuffer): FfiBknException {


        return when(buf.getInt()) {
            1 -> FfiBknException.Backend(
                FfiConverterString.read(buf),
                )
            2 -> FfiBknException.TableNotFound(
                FfiConverterString.read(buf),
                )
            3 -> FfiBknException.NotFound()
            4 -> FfiBknException.Encoding(
                FfiConverterString.read(buf),
                )
            5 -> FfiBknException.ReservedTableName(
                FfiConverterString.read(buf),
                )
            6 -> FfiBknException.DatabaseLocked(
                FfiConverterString.read(buf),
                )
            7 -> FfiBknException.DuplicateKey(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            8 -> FfiBknException.SchemaMismatch(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            9 -> FfiBknException.ConstraintViolation(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            10 -> FfiBknException.Corruption(
                FfiConverterString.read(buf),
                )
            11 -> FfiBknException.InvalidQuery(
                FfiConverterString.read(buf),
                )
            12 -> FfiBknException.DatabaseClosed()
            13 -> FfiBknException.TransactionInProgress()
            14 -> FfiBknException.TransactionClosed()
            15 -> FfiBknException.TransactionAborted(
                FfiConverterString.read(buf),
                )
            16 -> FfiBknException.InvalidArgument(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiBknException): ULong {
        return when(value) {
            is FfiBknException.Backend -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is FfiBknException.TableNotFound -> (
