use crate::graph::{EdgeId, NodeId};
use crate::relational::TableSchema;
use crate::value::{PropValue, Properties};
use crate::{BknError, StorageBackend};
use crate::db::Db;

/// A structured batch of graph nodes, graph edges, and relational rows
/// designed for high-performance atomic synchronization (e.g. codebase-recall indexing).
///
/// Relational rows are **upserted**: re-syncing a row whose primary key
/// already exists replaces it (secondary indexes stay consistent) instead of
/// failing, so the same batch can be applied repeatedly.
#[derive(Default, Debug, Clone)]
pub struct SyncBatch {
    pub nodes: Vec<(String, Properties)>,
    pub edges: Vec<(NodeId, String, NodeId, Properties)>,
    /// Edges whose endpoints may be nodes created by this same batch (see
    /// [`NodeRef`]). Created after `edges`.
    pub linked_edges: Vec<(NodeRef, String, NodeRef, Properties)>,
    pub relational_rows: Vec<(TableSchema, Vec<Properties>)>,
    pub relational_rows_with_pk: Vec<(TableSchema, Vec<(PropValue, Properties)>)>,
}

/// Appends `items` to the last group if it's for the same table, otherwise
/// starts a new group — keeps consecutive rows for one table in one bulk call.
fn push_grouped<T>(groups: &mut Vec<(TableSchema, Vec<T>)>, schema: TableSchema, items: Vec<T>) {
    if items.is_empty() {
        return;
    }
    match groups.last_mut() {
        Some((s, existing)) if *s == schema => existing.extend(items),
        _ => groups.push((schema, items)),
    }
}

/// An edge endpoint in a [`SyncBatch`]: an existing node, or the node at
/// `index` in this batch's `nodes` (whose id isn't known until it runs).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NodeRef {
    Existing(NodeId),
    New(usize),
}

impl From<NodeId> for NodeRef {
    fn from(id: NodeId) -> Self {
        NodeRef::Existing(id)
    }
}

impl NodeRef {
    fn resolve(self, created: &[NodeId]) -> Result<NodeId, BknError> {
        match self {
            NodeRef::Existing(id) => Ok(id),
            NodeRef::New(i) => created.get(i).copied().ok_or_else(|| {
                BknError::Encoding(format!("NodeRef::New({i}) is out of range: the batch creates {} node(s)", created.len()))
            }),
        }
    }
}

/// The result of executing a [`SyncBatch`], returning the sequential IDs
/// and primary keys generated during the atomic transaction.
#[derive(Default, Debug, Clone, PartialEq)]
pub struct SyncBatchResult {
    pub node_ids: Vec<NodeId>,
    pub edge_ids: Vec<EdgeId>,
    pub relational_pks: Vec<Vec<PropValue>>,
}

impl SyncBatch {
    pub fn new() -> Self {
        Self::default()
    }

    /// Adds a single graph node to the batch.
    pub fn add_node(&mut self, label: impl Into<String>, properties: Properties) -> &mut Self {
        self.nodes.push((label.into(), properties));
        self
    }

    /// Adds multiple graph nodes to the batch.
    pub fn add_nodes(&mut self, nodes: impl IntoIterator<Item = (impl Into<String>, Properties)>) -> &mut Self {
        self.nodes.extend(nodes.into_iter().map(|(l, p)| (l.into(), p)));
        self
    }

    /// Adds a single graph edge to the batch.
    pub fn add_edge(
        &mut self,
        from: NodeId,
        edge_type: impl Into<String>,
        to: NodeId,
        properties: Properties,
    ) -> &mut Self {
        self.edges.push((from, edge_type.into(), to, properties));
        self
    }

    /// Adds an edge whose endpoints may be nodes added to this same batch:
    /// `NodeRef::New(i)` is the `i`-th node added (0-based).
    pub fn add_linked_edge(
        &mut self,
        from: impl Into<NodeRef>,
        edge_type: impl Into<String>,
        to: impl Into<NodeRef>,
        properties: Properties,
    ) -> &mut Self {
        self.linked_edges.push((from.into(), edge_type.into(), to.into(), properties));
        self
    }

    /// Adds multiple graph edges to the batch.
    pub fn add_edges(
        &mut self,
        edges: impl IntoIterator<Item = (NodeId, impl Into<String>, NodeId, Properties)>,
    ) -> &mut Self {
        self.edges.extend(edges.into_iter().map(|(f, t, to, p)| (f, t.into(), to, p)));
        self
    }

    /// Adds a relational row. On an auto-increment schema a row without a
    /// pk gets a fresh one; a row that carries its pk is upserted.
    pub fn add_row(&mut self, schema: impl Into<TableSchema>, values: Properties) -> &mut Self {
        push_grouped(&mut self.relational_rows, schema.into(), vec![values]);
        self
    }

    /// Adds multiple relational rows (see [`SyncBatch::add_row`]).
    pub fn add_rows(&mut self, schema: impl Into<TableSchema>, rows: impl IntoIterator<Item = Properties>) -> &mut Self {
        push_grouped(&mut self.relational_rows, schema.into(), rows.into_iter().collect());
        self
    }

    /// Adds a relational row with an explicit caller-specified PK (e.g. NodeId).
    pub fn add_row_with_pk(&mut self, schema: impl Into<TableSchema>, pk: PropValue, values: Properties) -> &mut Self {
        push_grouped(&mut self.relational_rows_with_pk, schema.into(), vec![(pk, values)]);
        self
    }

    /// Adds multiple relational rows with explicit caller-specified PKs.
    pub fn add_rows_with_pk(
        &mut self,
        schema: impl Into<TableSchema>,
        rows: impl IntoIterator<Item = (PropValue, Properties)>,
    ) -> &mut Self {
        push_grouped(&mut self.relational_rows_with_pk, schema.into(), rows.into_iter().collect());
        self
    }
}

impl<B: StorageBackend> Db<B> {
    /// Executes a [`SyncBatch`] within a single ACID write transaction using bulk primitives.
    /// Reserves sequential node, edge, and relational PKs with minimal counter updates.
    /// Relational rows are upserted (see [`SyncBatch`]).
    pub fn sync_batch(&self, batch: SyncBatch) -> Result<SyncBatchResult, BknError> {
        self.write_tx(|wbatch| {
            let mut graph = wbatch.graph();
            let node_ids = graph.create_nodes_bulk(batch.nodes)?;
            let mut edges = batch.edges;
            for (from, edge_type, to, props) in batch.linked_edges {
                edges.push((from.resolve(&node_ids)?, edge_type, to.resolve(&node_ids)?, props));
            }
            let edge_ids = graph.create_edges_bulk(edges)?;

            let mut relational = wbatch.relational();
            let mut relational_pks = Vec::with_capacity(batch.relational_rows.len());
            for (schema, rows) in batch.relational_rows {
                let mut tbl = relational.table(schema);
                let pks = tbl.upsert_bulk(rows)?;
                relational_pks.push(pks);
            }

            for (schema, rows) in batch.relational_rows_with_pk {
                let mut tbl = relational.table(schema);
                tbl.upsert_with_pk_bulk(rows)?;
            }

            Ok(SyncBatchResult {
                node_ids,
                edge_ids,
                relational_pks,
            })
        })
    }
}

crates/bkndb-core/src/db/write_tx.rs:
//! [`Db::write_tx`] — the cross-model atomic transaction entry point.
//! Deliberately its own file, separate from [`crate::db::Db`]'s plain
//! accessors, so `db/mod.rs` stays a small, single-purpose "what facades
//! does `Db` expose" file.

use crate::db::{batch::DbWriteBatch, Db};
use crate::{BknError, StorageBackend, StorageWriteTx};

impl<B: StorageBackend> Db<B> {
    /// Runs `f` against one shared write transaction that can touch graph,
    /// relational, and raw KV together, committing only if `f` returns
    /// `Ok` — the same open/wrap/run/commit shape already proven by
    /// [`crate::relational::RelationalDb::write_tx`] and
    /// [`crate::graph::GraphDb::write_tx`], applied a third time.
    pub fn write_tx<F, R>(&self, f: F) -> Result<R, BknError>
    where
        F: for<'w> FnOnce(&mut DbWriteBatch<B::WriteTx<'w>>) -> Result<R, BknError>,
    {
        let wtx = self.backend.begin_write()?;
        let mut batch = DbWriteBatch::new(wtx);
        let result = f(&mut batch)?;
        batch.into_inner().commit()?;
        Ok(result)
    }
}

crates/bkndb-core/src/error.rs:
use std::fmt;

#[derive(Debug)]
pub enum BknError {
    Backend(String),
    TableNotFound(String),
    NotFound,
    Encoding(String),
    ReservedTableName(String),
    /// Another handle (in this or another process) already has the
    /// database file open for writing. Carries the path that was locked.
    DatabaseLocked(String),
    /// An insert with an explicit primary key collided with an existing row.
    DuplicateKey { table: String, key: String },
    /// A row's value doesn't match its declared column kind, or names a
    /// column the schema doesn't declare.
    SchemaMismatch { table: String, message: String },
    /// A NOT NULL or UNIQUE constraint would be violated.
    ConstraintViolation { table: String, message: String },
    /// Stored data failed an integrity check (checksum mismatch, truncated
    /// or malformed on-disk structure). Never retried or silently skipped.
    Corruption(String),
    /// A query-language statement (SQL, graph pattern) failed to parse or
    /// doesn't make sense — carries a message pointing at the problem.
    InvalidQuery(String),
}

impl fmt::Display for BknError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            BknError::Backend(msg) => write!(f, "storage backend error: {msg}"),
            BknError::TableNotFound(name) => write!(f, "table not found: {name}"),
            BknError::NotFound => write!(f, "key not found"),
            BknError::Encoding(msg) => write!(f, "encoding error: {msg}"),
            BknError::ReservedTableName(name) => write!(
                f,
                "table name '{name}' is reserved for bkndb-core's internal use (one of: {})",
                crate::RESERVED_TABLE_NAMES.join(", ")
            ),
            BknError::DatabaseLocked(path) => {
                write!(f, "database '{path}' is already open by another handle or process")
            }
            BknError::DuplicateKey { table, key } => {
                write!(f, "duplicate primary key {key} in table '{table}'")
            }
            BknError::SchemaMismatch { table, message } => {
                write!(f, "schema mismatch in table '{table}': {message}")
            }
            BknError::ConstraintViolation { table, message } => {
                write!(f, "constraint violation in table '{table}': {message}")
            }
            BknError::Corruption(msg) => write!(f, "data corruption detected: {msg}"),
            BknError::InvalidQuery(msg) => write!(f, "invalid query: {msg}"),
        }
    }
}

impl std::error::Error for BknError {}

crates/bkndb-core/src/graph/codec.rs:
//! Table names and binary key layout for the graph layer.
//!
//! Two encodings are at play here and they must not be confused:
//! - **Record values** (`NodeRecord`/`EdgeRecord`) are encoded with `bincode`,
//!   which is little-endian internally. That's fine — values are opaque
//!   blobs, nothing scans them byte-by-byte.
//! - **Keys** must sort, byte-lexicographically, in the same order as their
//!   numeric meaning, because `StorageReadTx::range` does a raw byte-range
//!   scan. That's only true for **big-endian fixed-width** integers: e.g.
//!   `7u64.to_be_bytes() < 100u64.to_be_bytes()` byte-wise, but the
//!   little-endian encodings would *not* compare correctly. So every id in a
//!   key (not in a value) is encoded with `to_be_bytes()`, independent of
//!   whatever `bincode` does for values.

use crate::graph::model::{EdgeId, NodeId};
use crate::TableSpec;

pub const NODES: TableSpec = TableSpec("nodes");
pub const EDGES: TableSpec = TableSpec("edges");
pub const ADJ_OUT: TableSpec = TableSpec("adj_out");
pub const ADJ_IN: TableSpec = TableSpec("adj_in");
pub const META: TableSpec = TableSpec("meta");

pub const NEXT_NODE_ID_KEY: &[u8] = b"next_node_id";
pub const NEXT_EDGE_ID_KEY: &[u8] = b"next_edge_id";

pub fn node_key(id: NodeId) -> [u8; 8] {
    id.0.to_be_bytes()
}

pub fn decode_node_id(bytes: &[u8]) -> Result<NodeId, crate::BknError> {
    let arr: [u8; 8] = bytes
        .try_into()
        .map_err(|_| crate::BknError::Encoding("invalid node key length".into()))?;
    Ok(NodeId(u64::from_be_bytes(arr)))
}

pub fn edge_key(id: EdgeId) -> [u8; 8] {
    id.0.to_be_bytes()
}

/// Exclusive upper bound for "every key starting with this node id's 8-byte
/// prefix, regardless of what follows" — used for cascade-delete scans and
/// prefix (any-edge-type) neighbor/degree scans. `None` only for
/// `id == u64::MAX`, an edge case callers must treat as "scan to the end of
/// the table" (`Bound::Unbounded`).
pub fn next_node_prefix(id: NodeId) -> Option<[u8; 8]> {
    id.0.checked_add(1).map(u64::to_be_bytes)
}

/// Length-prefixed edge_type: 2-byte BE length + UTF-8 bytes. Without the
/// length prefix, edge_type `"cal"` would be a byte-prefix of `"calls"`, and
/// a range scan bounded only by the `"cal"` prefix would incorrectly include
/// `"calls"` edges too. Comparing the length first (3 != 5) disambiguates
/// them regardless of shared leading bytes.
fn encode_edge_type(t: &str) -> Vec<u8> {
    let bytes = t.as_bytes();
    debug_assert!(bytes.len() <= u16::MAX as usize, "edge_type too long");
    let mut out = Vec::with_capacity(2 + bytes.len());
    out.extend_from_slice(&(bytes.len() as u16).to_be_bytes());
    out.extend_from_slice(bytes);
    out
}

/// adj_out key = from(8) ++ len(2) ++ edge_type(len) ++ to(8) ++ edge_id(8).
/// Value is empty; edge_id (and hence the canonical `edges` record) is
/// already recoverable from the key tail.
///
/// Worked example: node 42 --calls--> node 7 (edge_id 1001) and
/// node 42 --calls--> node 100 (edge_id 1002) produce
/// `be(42)++be16(5)++"calls"++be(7)++be(1001)` and
/// `be(42)++be16(5)++"calls"++be(100)++be(1002)`, which sort with the first
/// before the second because `be(7) < be(100)` byte-wise (fixed-width BE
/// makes numeric 7 < 100 hold as a byte comparison too, unlike variable
/// -length decimal text).
pub fn adj_out_key(from: NodeId, edge_type: &str, to: NodeId, edge: EdgeId) -> Vec<u8> {
    encode_adj_key(from, edge_type, to, edge)
}

pub fn adj_in_key(to: NodeId, edge_type: &str, from: NodeId, edge: EdgeId) -> Vec<u8> {
    encode_adj_key(to, edge_type, from, edge)
}

fn encode_adj_key(first: NodeId, edge_type: &str, second: NodeId, edge: EdgeId) -> Vec<u8> {
    let mut k = Vec::with_capacity(8 + 2 + edge_type.len() + 8 + 8);
    k.extend_from_slice(&first.0.to_be_bytes());
    k.extend_from_slice(&encode_edge_type(edge_type));
    k.extend_from_slice(&second.0.to_be_bytes());
    k.extend_from_slice(&edge.0.to_be_bytes());
    k
}

/// Inclusive start bound for "first=X, edge_type=Y, any second/edge_id" — a
/// strict byte-prefix of any full key with that (first, edge_type), and a
/// strict prefix always sorts as `Less` than anything it prefixes, so it is
/// a valid inclusive lower bound with no padding needed.
pub fn adj_type_prefix(first: NodeId, edge_type: &str) -> Vec<u8> {
    let mut k = Vec::with_capacity(8 + 2 + edge_type.len());
    k.extend_from_slice(&first.0.to_be_bytes());
    k.extend_from_slice(&encode_edge_type(edge_type));
    k
}

/// Inclusive upper bound for the same type-filtered scan. The suffix after
/// the type prefix is always exactly 16 bytes (second:8 + edge_id:8), so
/// appending 16 bytes of `0xFF` is a safe, overflow-free upper bound with no
/// last-byte-increment edge cases to worry about.
pub fn adj_type_upper_bound(first: NodeId, edge_type: &str) -> Vec<u8> {
    let mut k = adj_type_prefix(first, edge_type);
    k.extend_from_slice(&[0xFF; 16]);
    k
}

/// Decodes an adj_out or adj_in key back into its four physical fields:
/// (first_id, edge_type, second_id, edge_id). Field names are physical, not
/// semantic — callers know from which table they read whether `first` means
/// `from` or `to`.
pub fn decode_adj_key(key: &[u8]) -> (u64, String, u64, EdgeId) {
    let first = u64::from_be_bytes(key[0..8].try_into().unwrap());
    let len = u16::from_be_bytes(key[8..10].try_into().unwrap()) as usize;
    let edge_type = String::from_utf8(key[10..10 + len].to_vec()).expect("edge_type is valid utf8");
    let off = 10 + len;
    let second = u64::from_be_bytes(key[off..off + 8].try_into().unwrap());
    let edge_id = u64::from_be_bytes(key[off + 8..off + 16].try_into().unwrap());
    (first, edge_type, second, EdgeId(edge_id))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn adj_key_roundtrip() {
        let key = adj_out_key(NodeId(42), "calls", NodeId(7), EdgeId(1001));
        let (first, edge_type, second, edge_id) = decode_adj_key(&key);
        assert_eq!(first, 42);
        assert_eq!(edge_type, "calls");
        assert_eq!(second, 7);
        assert_eq!(edge_id, EdgeId(1001));
    }

    #[test]
    fn adj_key_sorts_by_second_id_numerically() {
        let key1 = adj_out_key(NodeId(42), "calls", NodeId(7), EdgeId(1001));
        let key2 = adj_out_key(NodeId(42), "calls", NodeId(100), EdgeId(1002));
        assert!(key1 < key2, "be(7) must sort before be(100) byte-wise");
    }

    #[test]
    fn edge_type_length_prefix_prevents_prefix_collision() {
        // "cal" must not be treated as a prefix match for "calls" entries.
        let cal_key = adj_out_key(NodeId(42), "cal", NodeId(1), EdgeId(1));
        let start = adj_type_prefix(NodeId(42), "calls");
        let end = adj_type_upper_bound(NodeId(42), "calls");
        assert!(
            !(start.as_slice()..=end.as_slice()).contains(&cal_key.as_slice()),
            "\"cal\"-typed edge must not fall inside a \"calls\"-filtered range"
        );
    }

    #[test]
    fn type_filtered_range_bounds_include_only_matching_type() {
        let calls_key1 = adj_out_key(NodeId(42), "calls", NodeId(7), EdgeId(1001));
        let calls_key2 = adj_out_key(NodeId(42), "calls", NodeId(100), EdgeId(1002));
        let imports_key = adj_out_key(NodeId(42), "imports", NodeId(5), EdgeId(2000));

        let start = adj_type_prefix(NodeId(42), "calls");
        let end = adj_type_upper_bound(NodeId(42), "calls");
        let range = start.as_slice()..=end.as_slice();

        assert!(range.contains(&calls_key1.as_slice()));
        assert!(range.contains(&calls_key2.as_slice()));
        assert!(!range.contains(&imports_key.as_slice()));
    }

    #[test]
    fn next_node_prefix_handles_max_id() {
        assert_eq!(next_node_prefix(NodeId(u64::MAX)), None);
        assert_eq!(next_node_prefix(NodeId(41)), Some(42u64.to_be_bytes()));
    }
}

