//! Answering `search_vector` from an index, with filter handling.
use super::*;

/// Answers a vector search from an index, or `None` when there's no usable
/// index (none on the column, another metric, empty) or a selective filter
/// makes scanning the filtered rows the better plan.
#[allow(clippy::too_many_arguments)]
pub(crate) fn search_in<R: StorageReadTx>(
    rtx: &R,
    schema: &TableSchema,
    column: &str,
    query: &[f32],
    limit: usize,
    metric: VectorMetric,
    filter: Option<&Query>,
    ef_search: Option<usize>,
) -> Result<Option<Vec<ScoredRow>>, BknError> {
    let Some(mut index) = Hnsw::load(rtx, schema.name(), column)? else { return Ok(None) };
    if index.metric != metric || index.meta.count == 0 {
        return Ok(None);
    }
    if query.len() != index.meta.dim as usize {
        return Err(BknError::InvalidQuery(format!(
            "vector index '{}' holds {}-dimensional vectors, the query has {}",
            index.name,
            index.meta.dim,
            query.len()
        )));
    }
    let Some(q) = index.prepare(query.to_vec()) else { return Ok(Some(Vec::new())) };
    let qnorm = query.iter().map(|x| (*x as f64).powi(2)).sum::<f64>().sqrt();
    let pk_kind = schema.primary_key_column().kind;
    let total = index.meta.count as usize;
    let mut ef = ef_search.unwrap_or((limit.saturating_mul(4)).max(64)).max(limit).max(1);
    loop {
        let found = index.search(rtx, &q, ef)?;
        let mut hits: Vec<(f64, Vec<u8>, ScoredRow)> = Vec::new();
        for pk in &found {
            let Some(row) = get_in(rtx, schema, &decode_sortable(pk_kind, pk)?)? else { continue };
            if filter.is_some_and(|f| !f.filters.iter().all(|e| e.eval(schema, &row))) {
                continue;
            }
            let Some(v) = row.values.get(column).and_then(vector_of) else { continue };
            let Some((s, goodness)) = score(metric, &v, query, qnorm) else { continue };
            hits.push((goodness, pk.clone(), ScoredRow { row, score: s }));
        }
        if hits.len() >= limit || filter.is_none() || found.len() < ef {
            hits.sort_by(|a, b| b.0.total_cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
            hits.truncate(limit);
            return Ok(Some(hits.into_iter().map(|(_, _, r)| r).collect()));
        }
        // The filter rejected too many candidates: widen, or scan instead.
        if ef >= total || ef >= MAX_EF {
            return Ok(None);
        }
        ef = ef.saturating_mul(4);
    }
}

crates/bkndb-core/src/relational/ann/sto:
//! On-disk layout of a vector index: keys, metadata, node and link encoding.
use super::*;

pub(super) fn registry_key(table: &str) -> Vec<u8> {
    format!("relann:{table}").into_bytes()
}

pub(super) fn meta_key(table: &str, column: &str) -> Vec<u8> {
    format!("relannmeta:{table}:{column}").into_bytes()
}

pub(super) fn nodes_table(table: &str, column: &str) -> TableSpec {
    TableSpec(intern(&format!("{table}__ann_{column}")))
}

pub(super) fn links_table(table: &str, column: &str) -> TableSpec {
    TableSpec(intern(&format!("{table}__annlnk_{column}")))
}

pub(super) fn pks_table(table: &str, column: &str) -> TableSpec {
    TableSpec(intern(&format!("{table}__annpk_{column}")))
}

pub(super) fn enc_err(e: impl std::fmt::Display) -> BknError {
    BknError::Encoding(e.to_string())
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub(super) struct AnnMeta {
    pub(super) metric: u8,
    pub(super) m: u32,
    pub(super) ef_construction: u32,
    /// 0 while no vector has been indexed.
    pub(super) dim: u32,
    pub(super) entry: Option<u64>,
    pub(super) max_level: u8,
    pub(super) next_id: u64,
    pub(super) count: u64,
}

pub(super) fn metric_code(metric: VectorMetric) -> u8 {
    match metric {
        VectorMetric::Cosine => 0,
        VectorMetric::Dot => 1,
        VectorMetric::Euclidean => 2,
    }
}

pub(super) fn metric_from(code: u8) -> Result<VectorMetric, BknError> {
    match code {
        0 => Ok(VectorMetric::Cosine),
        1 => Ok(VectorMetric::Dot),
        2 => Ok(VectorMetric::Euclidean),
        other => Err(BknError::Corruption(format!("unknown vector index metric {other}"))),
    }
}

/// Columns of `table` that have a vector index.
pub(crate) fn columns_in<R: StorageReadTx>(rtx: &R, table: &str) -> Result<Vec<String>, BknError> {
    match rtx.get(meta_table(), &registry_key(table))? {
        Some(bytes) => bincode::deserialize(&bytes).map_err(enc_err),
        None => Ok(Vec::new()),
    }
}

pub(super) fn save_columns<W: StorageWriteTx>(wtx: &mut W, table: &str, columns: &[String]) -> Result<(), BknError> {
    if columns.is_empty() {
        wtx.delete(meta_table(), &registry_key(table))
    } else {
        wtx.put(meta_table(), &registry_key(table), &bincode::serialize(columns).map_err(enc_err)?)
    }
}

pub(super) struct Node {
    pub(super) level: u8,
    pub(super) pk: Vec<u8>,
    pub(super) vector: Vec<f32>,
}

pub(super) fn encode_node(level: u8, pk: &[u8], vector: &[f32]) -> Vec<u8> {
    let mut out = Vec::with_capacity(5 + pk.len() + vector.len() * 4);
    out.push(level);
    out.extend_from_slice(&(pk.len() as u32).to_le_bytes());
    out.extend_from_slice(pk);
    for x in vector {
        out.extend_from_slice(&x.to_le_bytes());
    }
    out
}

pub(super) fn decode_node(bytes: &[u8]) -> Result<Node, BknError> {
    let bad = || BknError::Corruption("malformed vector index node".into());
    let (&level, rest) = bytes.split_first().ok_or_else(bad)?;
    let (len, rest) = rest.split_first_chunk::<4>().ok_or_else(bad)?;
    let len = u32::from_le_bytes(*len) as usize;
    if rest.len() < len || !(rest.len() - len).is_multiple_of(4) {
        return Err(bad());
    }
    let (pk, vector) = rest.split_at(len);
    Ok(Node { level, pk: pk.to_vec(), vector: vector.as_chunks::<4>().0.iter().map(|c| f32::from_le_bytes(*c)).collect() })
}

pub(super) fn link_key(id: u64, layer: u8) -> [u8; 9] {
    let mut k = [0u8; 9];
    k[..8].copy_from_slice(&id.to_be_bytes());
    k[8] = layer;
    k
}

/// Deterministic level for a new node: the usual `floor(-ln(U) / ln(m))`
/// with `U` drawn from a hash of the pk, so a rebuild reproduces the graph.
pub(super) fn level_for(pk: &[u8], m: usize) -> u8 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in pk {
        h ^= *b as u64;
        h = h.wrapping_mul(0x0100_0000_01b3);
    }
    // splitmix64 finalizer
    h = h.wrapping_add(0x9e37_79b9_7f4a_7c15);
    h = (h ^ (h >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    h = (h ^ (h >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    h ^= h >> 31;
    let u = ((h >> 11) as f64 + 1.0) / (1u64 << 53) as f64; // (0, 1]
    let level = (-u.ln() / (m as f64).ln()).floor();
    (level as u64).min(MAX_LEVEL as u64) as u8
}

/// A node and its distance to whatever is being searched for, ordered by
/// distance (ties by id).
#[derive(Debug, Clone, Copy)]
pub(super) struct Cand {
    pub(super) d: f32,
    pub(super) id: u64,
}

impl PartialEq for Cand {
    fn eq(&self, other: &Self) -> bool {
        self.cmp(other) == Ordering::Equal
    }
}
impl Eq for Cand {}
impl PartialOrd for Cand {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for Cand {
    fn cmp(&self, other: &Self) -> Ordering {
        self.d.total_cmp(&other.d).then_with(|| self.id.cmp(&other.id))
    }
}

crates/bkndb-core/src/relational/catalog:
//! Persistent schema catalog: every table created through
//! [`crate::relational::RelationalDb::create_table`] /
//! [`crate::relational::RelationalDb::ensure_table`] has its [`TableSchema`]
//! stored in the shared `meta` table, so it can be listed, looked up by name
//! (e.g. from language bindings that have no compile-time schema), migrated
//! and dropped. Tables used only through a static `RelSchema` keep working
//! without ever being registered.
use std::collections::HashSet;
use std::ops::Bound;

use crate::relational::codec::{
    base_table, catalog_key, decode_table_def, encode_row, encode_table_def, index_key, index_table, meta_table,
    prefix_upper_bound, row_counter_key, sortable_encode, CATALOG_PREFIX,
};
use crate::relational::db::{scan_all_in, validate_row, Row};
use crate::relational::schema::TableSchema;
use crate::value::PropValue;
use crate::{BknError, StorageReadTx, StorageWriteTx, TableSpec};

pub(crate) fn load_schema_in<R: StorageReadTx>(rtx: &R, name: &str) -> Result<Option<TableSchema>, BknError> {
    match rtx.get(meta_table(), &catalog_key(name))? {
        Some(bytes) => Ok(Some(TableSchema::from_def(decode_table_def(&bytes)?))),
        None => Ok(None),
    }
}

pub(crate) fn require_schema_in<R: StorageReadTx>(rtx: &R, name: &str) -> Result<TableSchema, BknError> {
    crate::check_table_name(name)?;
    load_schema_in(rtx, name)?.ok_or_else(|| BknError::TableNotFound(name.to_string()))
}

pub(crate) fn list_schemas_in<R: StorageReadTx>(rtx: &R) -> Result<Vec<TableSchema>, BknError> {
    let end = prefix_upper_bound(CATALOG_PREFIX).expect("catalog prefix is not all 0xFF");
    rtx.range(meta_table(), Bound::Included(CATALOG_PREFIX), Bound::Excluded(&end))?
        .into_iter()
        .map(|(_, v)| Ok(TableSchema::from_def(decode_table_def(&v)?)))
        .collect()
}

/// Registers `schema`. Returns `false` (and changes nothing) if an identical
/// definition is already registered; errors if a *different* one is.
pub(crate) fn create_table_in<W: StorageWriteTx>(wtx: &mut W, schema: &TableSchema) -> Result<bool, BknError> {
    crate::check_table_name(schema.name())?;
    match load_schema_in(wtx, schema.name())? {
        Some(existing) if existing == *schema => Ok(false),
        Some(_) => Err(mismatch(
            schema,
            "table already exists with a different definition (use ensure_table to migrate it)".to_string(),
        )),
        None => {
            adopt_in(wtx, schema)?;
            Ok(true)
        }
    }
}

/// Makes the stored table match `schema`: creates it if absent, otherwise
/// migrates existing rows and indexes to the new definition. Atomic with the
/// caller's transaction, so a failed migration changes nothing.
pub(crate) fn ensure_table_in<W: StorageWriteTx>(wtx: &mut W, schema: &TableSchema) -> Result<(), BknError> {
    crate::check_table_name(schema.name())?;
    match load_schema_in(wtx, schema.name())? {
        None => adopt_in(wtx, schema),
        Some(old) if old == *schema => Ok(()),
        Some(old) => {
            migrate_in(wtx, &old, schema)?;
            #[cfg(feature = "search")]
            crate::relational::search::retain_valid_in(wtx, schema.name(), Some(schema))?;
            Ok(())
        }
    }
}

/// Removes a registered table: rows, indexes, pk counter and catalog entry.
/// Returns `false` if no such table is registered.
pub(crate) fn drop_table_in<W: StorageWriteTx>(wtx: &mut W, name: &str) -> Result<bool, BknError> {
    crate::check_table_name(name)?;
    let Some(schema) = load_schema_in(wtx, name)? else {
        return Ok(false);
    };
    clear_table(wtx, base_table(&schema))?;
    for col in schema.indexed_columns() {
        clear_table(wtx, index_table(&schema, col))?;
    }
    wtx.delete(meta_table(), &row_counter_key(name))?;
    wtx.delete(meta_table(), &catalog_key(name))?;
    #[cfg(feature = "search")]
    crate::relational::search::retain_valid_in(wtx, name, None)?;
    Ok(true)
}

fn mismatch(schema: &TableSchema, message: String) -> BknError {
    BknError::SchemaMismatch { table: schema.name().to_string(), message }
}

fn store_def<W: StorageWriteTx>(wtx: &mut W, schema: &TableSchema) -> Result<(), BknError> {
    wtx.put(meta_table(), &catalog_key(schema.name()), &encode_table_def(schema.def())?)
}

/// Registers a table not yet in the catalog. Rows may already exist (a table
/// previously used only through a static `RelSchema`); their indexes are
/// rebuilt, which also repairs indexes added to a static schema after rows
/// were written (those were never backfilled).
fn adopt_in<W: StorageWriteTx>(wtx: &mut W, schema: &TableSchema) -> Result<(), BknError> {
    let rows = scan_all_in(wtx, schema)?;
    if !rows.is_empty() {
        for col in schema.indexed_columns() {
            rebuild_index(wtx, schema, col, &rows)?;
        }
    }
    store_def(wtx, schema)
}

fn migrate_in<W: StorageWriteTx>(wtx: &mut W, old: &TableSchema, new: &TableSchema) -> Result<(), BknError> {
    if old.primary_key() != new.primary_key()
        || old.primary_key_column().kind != new.primary_key_column().kind
        || old.auto_increment_pk() != new.auto_increment_pk()
    {
        return Err(mismatch(new, "the primary key and auto-increment setting cannot be changed".to_string()));
    }
    for c in new.columns() {
        if let Some(o) = old.column(&c.name)
            && o.kind != c.kind
        {
            return Err(mismatch(new, format!("column '{}' cannot change kind from {:?} to {:?}", c.name, o.kind, c.kind)));
        }
    }

    // Rewrite rows: drop removed columns, fill defaults of added ones, and
    // re-validate against the new constraints (e.g. a column made NOT NULL).
    let mut rows = scan_all_in(wtx, old)?;
    for row in &mut rows {
        let before = row.values.clone();
        row.values.retain(|k, _| new.column(k).is_some());
        for c in new.columns() {
            if old.column(&c.name).is_none()
                && !row.values.contains_key(&c.name)
                && let Some(d) = &c.default
            {
                row.values.insert(c.name.clone(), d.clone());
            }
        }
        validate_row(new, &row.pk, &row.values)?;
        if row.values != before {
            wtx.put(base_table(new), &sortable_encode(&row.pk)?, &encode_row(&row.values)?)?;
        }
    }

    for col in old.indexed_columns() {
        if !new.is_indexed(col) {
            clear_table(wtx, index_table(old, col))?;
        }
    }
    for col in new.indexed_columns() {
        let newly_unique = new.column(col).is_some_and(|c| c.unique) && !old.column(col).is_some_and(|c| c.unique);
        if !old.is_indexed(col) || newly_unique {
            rebuild_index(wtx, new, col, &rows)?;
        }
    }
    store_def(wtx, new)
}

/// Rewrites one column's index from scratch over `rows`, enforcing UNIQUE.
fn rebuild_index<W: StorageWriteTx>(wtx: &mut W, schema: &TableSchema, col: &str, rows: &[Row]) -> Result<(), BknError> {
    let table = index_table(schema, col);
    clear_table(wtx, table)?;
    let unique = schema.column(col).is_some_and(|c| c.unique);
    let mut seen = HashSet::new();
    for row in rows {
        let Some(v) = row.get(schema, col).filter(|v| !matches!(v, PropValue::Null)) else {
            continue;
        };
        if unique && !seen.insert(sortable_encode(v)?) {
            return Err(BknError::ConstraintViolation {
                table: schema.name().to_string(),
                message: format!("cannot make '{col}' UNIQUE: value {v:?} appears more than once"),
            });
        }
        wtx.put(table, &index_key(v, &row.pk)?, &[])?;
    }
    Ok(())
}

fn clear_table<W: StorageWriteTx>(wtx: &mut W, table: TableSpec) -> Result<(), BknError> {
    for (k, _) in wtx.range(table, Bound::Unbounded, Bound::Unbounded)? {
        wtx.delete(table, &k)?;
    }
    Ok(())
}

crates/bkndb-core/src/relational/codec.r:
use std::collections::HashSet;
use std::ops::Bound;
use std::sync::{Mutex, OnceLock};

use crate::relational::schema::{ColumnKind, TableDef, TableSchema};
use crate::value::{PropValue, Properties};
use crate::{BknError, StorageWriteTx, TableSpec};

/// Shared meta/counter table. Same physical table name as the graph layer's
/// own `META` (`crates/bkndb-core/src/graph/codec.rs`) — intentional: both
/// layers can coexist over one backend without a name collision because
/// counter keys are namespaced (`next_node_id`/`next_edge_id` vs
/// `relnext:<table>`), so sharing one physical table just avoids growing
/// the table count instead of causing conflicts.
const META: TableSpec = TableSpec("meta");

/// Returns a `'static` copy of `name`, leaking each distinct string at most
/// once per process. `TableSpec` requires `&'static str`, but table names
/// of runtime-defined tables (and every derived index table name) are only
/// known at runtime; caching by content keeps the leak bounded by the number
/// of distinct table/index names a process ever touches.
pub(crate) fn intern(name: &str) -> &'static str {
    static CACHE: OnceLock<Mutex<HashSet<&'static str>>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(HashSet::new()));
    let mut guard = cache.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
    if let Some(&existing) = guard.get(name) {
        return existing;
    }
    let leaked: &'static str = Box::leak(name.to_string().into_boxed_str());
    guard.insert(leaked);
    leaked
}

pub fn base_table(schema: &TableSchema) -> TableSpec {
    schema.base_table()
}

/// The physical `TableSpec` backing one column's secondary index:
/// `<table>__idx_<column>`.
pub fn index_table(schema: &TableSchema, column: &str) -> TableSpec {
    index_table_named(schema.name(), column)
}

pub fn index_table_named(table: &str, column: &str) -> TableSpec {
    TableSpec(intern(&format!("{table}__idx_{column}")))
}

/// Catalog entries live in the shared `meta` table under this prefix,
/// one per table: `relschema:<table name>` → `CATALOG_VERSION ++ bincode(TableDef)`.
pub(crate) const CATALOG_PREFIX: &[u8] = b"relschema:";
const CATALOG_VERSION: u8 = 1;

pub(crate) fn catalog_key(table: &str) -> Vec<u8> {
    let mut k = CATALOG_PREFIX.to_vec();
    k.extend_from_slice(table.as_bytes());
    k
}

pub(crate) fn encode_table_def(def: &TableDef) -> Result<Vec<u8>, BknError> {
    let mut out = vec![CATALOG_VERSION];
    out.extend(bincode::serialize(def).map_err(|e| BknError::Encoding(e.to_string()))?);
    Ok(out)
}

pub(crate) fn decode_table_def(bytes: &[u8]) -> Result<TableDef, BknError> {
    match bytes.split_first() {
        Some((&CATALOG_VERSION, rest)) => bincode::deserialize(rest).map_err(|e| BknError::Encoding(e.to_string())),
        Some((v, _)) => Err(BknError::Encoding(format!("unsupported catalog entry version {v}"))),
        None => Err(BknError::Encoding("empty catalog entry".to_string())),
    }
}

pub(crate) fn meta_table() -> TableSpec {
    META
}

/// Sortable ("memcomparable") byte encoding for a scalar value used as a
/// primary key or index key. Only `Int`/`Str` are supported as key material.
///
/// - `Int`: sign-bit flip then big-endian bytes. Plain `to_be_bytes()` of a
///   signed integer does NOT sort negatives correctly byte-lexicographically
///   (a negative `i64`'s top bit is 1, so it would sort *after* every
///   positive value); flipping the sign bit first fixes this, the standard
///   trick for memcomparable signed-integer encodings.
/// - `Str`: raw UTF-8 bytes plus a single trailing `0x00` terminator, so a
///   string that is a strict prefix of another still compares correctly
///   (`"ab\0" < "abc\0"` because the third byte `0x00 < b'c'`). This assumes
///   values never contain an embedded NUL byte — a real constraint of this
///   scheme, acceptable for this project's use (paths, identifiers, names).
pub fn sortable_encode(value: &PropValue) -> Result<Vec<u8>, BknError> {
    crate::value::sortable_key(value).ok_or_else(|| {
        BknError::Encoding(match value {
            PropValue::Str(_) => "strings used as a primary key or indexed value cannot contain a NUL byte".to_string(),
            _ => "only Int/Str/Timestamp/Uuid values can be used as a primary key or indexed column".to_string(),
        })
    })
}

pub fn decode_sortable(kind: ColumnKind, bytes: &[u8]) -> Result<PropValue, BknError> {
    match kind {
        ColumnKind::Int | ColumnKind::Timestamp => {
            let raw: [u8; 8] = bytes
                .try_into()
                .map_err(|_| BknError::Encoding("corrupt sortable int key".to_string()))?;
            let n = (u64::from_be_bytes(raw) ^ 0x8000_0000_0000_0000) as i64;
            Ok(if kind == ColumnKind::Int { PropValue::Int(n) } else { PropValue::Timestamp(n) })
        }
        ColumnKind::Uuid => {
            let raw: [u8; 16] = bytes
                .try_into()
                .map_err(|_| BknError::Encoding("corrupt sortable uuid key".to_string()))?;
            Ok(PropValue::Uuid(raw))
        }
        ColumnKind::Str => {
            let (last, rest) = bytes
                .split_last()
                .ok_or_else(|| BknError::Encoding("empty sortable str key".to_string()))?;
            if *last != 0 {
                return Err(BknError::Encoding(
                    "sortable str key missing terminator".to_string(),
                ));
            }
            let s = String::from_utf8(rest.to_vec()).map_err(|e| BknError::Encoding(e.to_string()))?;
            Ok(PropValue::Str(s))
        }
        _ => Err(BknError::Encoding(
            "only Int/Str/Timestamp/Uuid columns support sortable decoding".to_string(),
        )),
    }
}

/// index_key = sortable(indexed_value) ++ sortable(pk) — appending the pk
/// disambiguates multiple rows sharing the same indexed value, the same
/// pattern `adj_out_key` uses to append an edge id after a shared
/// (from, edge_type) prefix.
pub fn index_key(indexed_value: &PropValue, pk: &PropValue) -> Result<Vec<u8>, BknError> {
    let mut k = sortable_encode(indexed_value)?;
    k.extend(sortable_encode(pk)?);
    Ok(k)
}

/// Exclusive upper bound for "every key starting with exactly this byte
/// prefix" — a generic byte-string successor: increments the last byte
/// that is < 0xFF, truncating anything after it. `None` only if `prefix`
/// is entirely `0xFF` bytes, which never happens for real encoded values.
pub fn prefix_upper_bound(prefix: &[u8]) -> Option<Vec<u8>> {
    let mut out = prefix.to_vec();
    while let Some(last) = out.pop() {
        if last != 0xFF {
            out.push(last + 1);
            return Some(out);
        }
    }
    None
}

/// Computes range bounds for prefix scan over a sortable string secondary index.
pub fn sortable_str_prefix_bounds(prefix: &str) -> (Bound<Vec<u8>>, Bound<Vec<u8>>) {
    if prefix.is_empty() {
        (Bound::Unbounded, Bound::Unbounded)
    } else {
        let p_bytes = prefix.as_bytes().to_vec();
        let hi = match prefix_upper_bound(&p_bytes) {
            Some(ub) => Bound::Excluded(ub),
            None => Bound::Unbounded,
        };
        (Bound::Included(p_bytes), hi)
    }
}


pub(crate) fn row_counter_key(table: &str) -> Vec<u8> {
    format!("relnext:{table}").into_bytes()
}


/// Reserves a contiguous block of `count` primary keys for `schema`,
/// updating the counter in `META` once. Returns the starting primary key.
pub fn reserve_pks<W: StorageWriteTx>(
    wtx: &mut W,
    schema: &TableSchema,
    count: u64,
) -> Result<i64, BknError> {
    if count == 0 {
        return Ok(0);
    }
    let key = row_counter_key(schema.name());
    let current = match wtx.get(META, &key)? {
        Some(bytes) => u64::from_be_bytes(
            bytes
                .as_slice()
                .try_into()
                .map_err(|_| BknError::Encoding("corrupt relational id counter".to_string()))?,
        ),
        None => 1,
    };
    wtx.put(META, &key, &(current + count).to_be_bytes())?;
    Ok(current as i64)
}

/// Makes sure future auto-increment allocations for `schema` start after
/// `pk` — needed whenever a row is written with an explicit pk (upsert) on
/// an auto-increment table, or the counter could later hand out that pk
/// again and collide.
pub fn bump_pk_counter_past<W: StorageWriteTx>(wtx: &mut W, schema: &TableSchema, pk: i64) -> Result<(), BknError> {
    if pk < 1 {
        return Ok(());
    }
    let key = row_counter_key(schema.name());
    let current = match wtx.get(META, &key)? {
        Some(bytes) => u64::from_be_bytes(
            bytes
                .as_slice()
                .try_into()
                .map_err(|_| BknError::Encoding("corrupt relational id counter".to_string()))?,
        ),
        None => 1,
    };
    let needed = pk as u64 + 1;
    if needed > current {
        wtx.put(META, &key, &needed.to_be_bytes())?;
    }
    Ok(())
}

/// The byte length of an indexed value's encoding at the start of one of
/// its index keys — `Int` is always fixed-width (8 bytes); `Str` is found
/// by scanning for its `0x00` terminator (see [`sortable_encode`]'s doc
/// comment for the constraint this relies on). Used to split an index key
/// (`value_bytes ++ pk_bytes`) back into its two parts during a range scan,
/// where (unlike an exact-match lookup) the caller doesn't already know the
/// queried value's exact encoded length up front.
fn indexed_value_len(kind: ColumnKind, key: &[u8]) -> Result<usize, BknError> {
    match kind {
        ColumnKind::Int | ColumnKind::Timestamp => Ok(8),
        ColumnKind::Uuid => Ok(16),
        ColumnKind::Str => key
            .iter()
            .position(|&b| b == 0)
            .map(|pos| pos + 1)
            .ok_or_else(|| BknError::Encoding("index key missing str terminator".to_string())),
        _ => Err(BknError::Encoding(
            "only Int/Str/Timestamp/Uuid columns support indexing".to_string(),
        )),
    }
}

/// Splits a full index key (`value_bytes ++ pk_bytes`) into the pk-only
/// suffix, decoded via `pk_kind`.
pub fn pk_from_index_key(indexed_kind: ColumnKind, pk_kind: ColumnKind, key: &[u8]) -> Result<PropValue, BknError> {
    let split = indexed_value_len(indexed_kind, key)?;
    decode_sortable(pk_kind, &key[split..])
}

/// Converts a value-level range bound into a byte-level bound over index
/// keys (which are `value_bytes ++ pk_bytes`, always longer than the bare
/// encoded value). A bare `Included(value_bytes)` already works correctly
/// as a byte lower bound (any extension of it sorts after it), but
/// `Excluded(value)` must skip past every possible pk-suffixed extension of
/// `value`'s bytes, not just the bare bytes themselves — hence
/// `prefix_upper_bound`. The `None` case (bytes are all `0xFF`) is a
/// vanishingly rare edge case for real column values; falling back to
/// `Unbounded` slightly over-includes there rather than under-including.
pub fn lower_bound_bytes(bound: &Bound<PropValue>) -> Result<Bound<Vec<u8>>, BknError> {
    match bound {
        Bound::Unbounded => Ok(Bound::Unbounded),
        Bound::Included(v) => Ok(Bound::Included(sortable_encode(v)?)),
        Bound::Excluded(v) => {
            let enc = sortable_encode(v)?;
            Ok(match prefix_upper_bound(&enc) {
                Some(b) => Bound::Included(b),
                None => Bound::Unbounded,
            })
        }
    }
}

/// Upper-bound counterpart of [`lower_bound_bytes`]. `Excluded(value)` works
/// as a bare byte bound directly (every pk-suffixed extension of `value`'s
/// bytes sorts after the bare bytes, so it's naturally excluded already);
/// `Included(value)` must include every such extension, hence
/// `prefix_upper_bound` as the exclusive cutoff.
pub fn upper_bound_bytes(bound: &Bound<PropValue>) -> Result<Bound<Vec<u8>>, BknError> {
    match bound {
        Bound::Unbounded => Ok(Bound::Unbounded),
        Bound::Excluded(v) => Ok(Bound::Excluded(sortable_encode(v)?)),
        Bound::Included(v) => {
            let enc = sortable_encode(v)?;
            Ok(match prefix_upper_bound(&enc) {
                Some(b) => Bound::Excluded(b),
                None => Bound::Unbounded,
            })
        }
    }
}

pub fn encode_row(properties: &Properties) -> Result<Vec<u8>, BknError> {
    bincode::serialize(properties).map_err(|e| BknError::Encoding(e.to_string()))
}

pub fn decode_row(bytes: &[u8]) -> Result<Properties, BknError> {
    bincode::deserialize(bytes).map_err(|e| BknError::Encoding(e.to_string()))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn int_sortable_encoding_preserves_numeric_order() {
        let mut values = vec![-100i64, -1, 0, 1, 100, i64::MIN, i64::MAX];
        let mut encoded: Vec<(i64, Vec<u8>)> = values
            .iter()
            .map(|&v| (v, sortable_encode(&PropValue::Int(v)).unwrap()))
            .collect();
        encoded.sort_by(|a, b| a.1.cmp(&b.1));
        values.sort();
        let sorted_values: Vec<i64> = encoded.into_iter().map(|(v, _)| v).collect();
        assert_eq!(sorted_values, values);
    }

    #[test]
    fn int_sortable_roundtrip() {
        for v in [-100i64, -1, 0, 1, 100, i64::MIN, i64::MAX] {
            let bytes = sortable_encode(&PropValue::Int(v)).unwrap();
            let decoded = decode_sortable(ColumnKind::Int, &bytes).unwrap();
            assert_eq!(decoded, PropValue::Int(v));
        }
    }

    #[test]
    fn str_sortable_encoding_preserves_prefix_order() {
        let a = sortable_encode(&PropValue::Str("ab".to_string())).unwrap();
        let b = sortable_encode(&PropValue::Str("abc".to_string())).unwrap();
        let c = sortable_encode(&PropValue::Str("abd".to_string())).unwrap();
        assert!(a < b, "\"ab\" must sort before \"abc\"");
        assert!(b < c, "\"abc\" must sort before \"abd\"");
    }

    #[test]
    fn str_sortable_roundtrip() {
        for s in ["", "hello", "a longer string with spaces"] {
            let bytes = sortable_encode(&PropValue::Str(s.to_string())).unwrap();
            let decoded = decode_sortable(ColumnKind::Str, &bytes).unwrap();
            assert_eq!(decoded, PropValue::Str(s.to_string()));
        }
    }

    #[test]
    fn index_table_is_cached_across_calls() {
        let t1 = index_table_named("widgets", "color");
        let t2 = index_table_named("widgets", "color");
        assert_eq!(t1.0, "widgets__idx_color");
        assert_eq!(t1.0.as_ptr(), t2.0.as_ptr(), "must return the same leaked str, not re-leak");
    }

    #[test]
    fn strings_with_nul_are_rejected_as_key_material() {
        let with_nul = String::from_utf8(vec![b'a', 0, b'b']).unwrap();
        assert!(sortable_encode(&PropValue::Str(with_nul)).is_err());
    }
}

use std::ops::Bound;
use std::sync::Arc;

use crate::relational::catalog;
use crate::relational::codec::{
    base_table, bump_pk_counter_past, decode_row, decode_sortable, encode_row, index_key,
    index_table, lower_bound_bytes, pk_from_index_key, reserve_pks, sortable_encode,
    sortable_str_prefix_bounds, upper_bound_bytes,
};
use crate::relational::query::{DeleteQuery, SelectQuery, UpdateQuery};
use crate::relational::schema::{ColumnKind, HasPrimaryKey, TableSchema};
use crate::value::{PropValue, Properties};
use crate::{BknError, StorageBackend, StorageReadTx, StorageWriteTx};

mod table;
mod write;
mod read;

pub use table::*;
pub(crate) use write::*;
pub(crate) use read::*;

#[derive(Debug, Clone, PartialEq)]
pub struct Row {
    pub pk: PropValue,
    pub values: Properties,
}

impl Row {
    /// Looks up a column's value by name, transparently resolving the
    /// primary-key column to `self.pk` — the row's stored `values` never
    /// contains the pk column (it lives in the row key, not the value), so
    /// callers that don't special-case it would otherwise always miss it.
    /// Accepts either a static `RelSchema` or a `TableSchema`.
    pub fn get<S: HasPrimaryKey + ?Sized>(&self, schema: &S, column: &str) -> Option<&PropValue> {
        if column == schema.primary_key_name() {
            Some(&self.pk)
        } else {
            self.values.get(column)
        }
    }
}

/// Relational (row/column) facade layered on top of a raw [`StorageBackend`],
/// sharing the same backend instance a [`crate::graph::GraphDb`] can use —
/// that shared `Arc<B>` is what makes the two layers "hybrid" rather than
/// two unrelated databases.
pub struct RelationalDb<B: StorageBackend> {
    pub(crate) backend: Arc<B>,
}

impl<B: StorageBackend> RelationalDb<B> {
    pub fn new(backend: B) -> Self {
        Self::from_arc(Arc::new(backend))
    }

    pub fn from_arc(backend: Arc<B>) -> Self {
        Self { backend }
    }

    /// A handle on the table described by `schema` (a `&RelSchema` static or
    /// a [`TableSchema`]); the table doesn't have to be registered in the
    /// catalog.
    ///
    /// Panics if the name collides with one of `bkndb-core`'s reserved
    /// internal table names (see [`crate::RESERVED_TABLE_NAMES`]) — a
    /// schema-authoring bug caught at first use, not a recoverable runtime
    /// condition. (A [`TableSchema`] built with its builder can never have a
    /// reserved name.)
    pub fn table(&self, schema: impl Into<TableSchema>) -> RelTable<'_, B> {
        let schema = schema.into();
        crate::check_table_name(schema.name()).unwrap_or_else(|e| panic!("{e}"));
        RelTable {
            db: self,
            table: TableRef {
                schema,
                by_name: false,
            },
        }
    }

    /// A handle on a table registered in the catalog, by name. The handle
    /// always uses the table's current definition, so it stays valid across
    /// migrations.
    pub fn table_named(&self, name: &str) -> Result<RelTable<'_, B>, BknError> {
        let rtx = self.backend.begin_read()?;
        let schema = catalog::require_schema_in(&rtx, name)?;
        Ok(RelTable {
            db: self,
            table: TableRef {
                schema,
                by_name: true,
            },
        })
    }

    /// Registers a new table. Returns `false` if an identical definition was
    /// already registered; errors if a different one is (see
    /// [`RelationalDb::ensure_table`] for migrating).
    pub fn create_table(&self, schema: impl Into<TableSchema>) -> Result<bool, BknError> {
        let schema = schema.into();
        self.write(|wtx| catalog::create_table_in(wtx, &schema))
    }

    /// Creates the table if needed, or migrates the registered one to match
    /// `schema`: added/removed columns (defaults are backfilled into existing
    /// rows), changed NOT NULL / UNIQUE constraints (validated against
    /// existing rows), and added/removed indexes (new ones are backfilled).
    /// The primary key and existing columns' kinds can't change. Atomic.
    ///
    /// Also the way to adopt a table previously used only through a static
    /// `RelSchema`: its indexes are rebuilt from the existing rows.
    pub fn ensure_table(&self, schema: impl Into<TableSchema>) -> Result<(), BknError> {
        let schema = schema.into();
        self.write(|wtx| catalog::ensure_table_in(wtx, &schema))
    }

    /// Deletes a registered table with all its rows and indexes. Returns
    /// `false` if no such table is registered.
    pub fn drop_table(&self, name: &str) -> Result<bool, BknError> {
        self.write(|wtx| catalog::drop_table_in(wtx, name))
    }

    /// Adds a (backfilled) secondary index to a registered table.
    pub fn create_index(&self, table: &str, column: &str) -> Result<(), BknError> {
        self.write(|wtx| {
            let schema = catalog::require_schema_in(wtx, table)?
                .to_builder()
                .index(column)
                .build()?;
            catalog::ensure_table_in(wtx, &schema)
        })
    }

    /// Removes a secondary index (and any UNIQUE constraint relying on it).
    pub fn drop_index(&self, table: &str, column: &str) -> Result<(), BknError> {
        self.write(|wtx| {
            let schema = catalog::require_schema_in(wtx, table)?
                .to_builder()
                .drop_index(column)
                .build()?;
            catalog::ensure_table_in(wtx, &schema)
        })
    }

    pub fn table_schema(&self, name: &str) -> Result<Option<TableSchema>, BknError> {
        catalog::load_schema_in(&self.backend.begin_read()?, name)
    }

    /// Runs one SQL statement (see [`crate::lang::sql`] for the supported
    /// subset): a query in a read snapshot, anything else in its own atomic
    /// write transaction.
    ///
    /// ```ignore
    /// db.sql("SELECT name FROM users WHERE age >= ? ORDER BY name", vec![18.into()])?;
    /// ```
    pub fn sql(&self, sql: &str, params: impl Into<crate::lang::Params>) -> Result<crate::lang::sql::SqlOutput, BknError> {
        let stmt = crate::lang::sql::parse(sql)?;
        let params = params.into();
        if stmt.is_read_only() {
            crate::lang::sql::execute_read(&self.backend.begin_read()?, &stmt, &params)
        } else {
            self.write(|wtx| crate::lang::sql::execute(wtx, &stmt, &params))
        }
    }

    /// Every table registered in the catalog, sorted by name.
    pub fn list_tables(&self) -> Result<Vec<TableSchema>, BknError> {
        catalog::list_schemas_in(&self.backend.begin_read()?)
    }

    pub(crate) fn write<R>(
        &self,
        f: impl for<'w> FnOnce(&mut B::WriteTx<'w>) -> Result<R, BknError>,
    ) -> Result<R, BknError> {
        let mut wtx = self.backend.begin_write()?;
        let r = f(&mut wtx)?;
        wtx.commit()?;
        Ok(r)
    }

    /// Runs `f` against one shared write transaction spanning however many
    /// tables it touches (via [`crate::relational::txn::RelWriteBatch::table`]),
    /// committing only if `f` returns `Ok`. An `Err` return leaves the write
    /// tx uncommitted and it is simply dropped — every [`StorageWriteTx`]
    /// backend buffers writes until `commit()`, so a dropped, uncommitted tx
    /// is already a no-op rollback with no extra bookkeeping needed here.
    pub fn write_tx<F, R>(&self, f: F) -> Result<R, BknError>
    where
        F: for<'w> FnOnce(
            &mut crate::relational::txn::RelWriteBatch<B::WriteTx<'w>>,
        ) -> Result<R, BknError>,
    {
        let wtx = self.backend.begin_write()?;
        let mut batch = crate::relational::txn::RelWriteBatch::new(wtx);
        let result = f(&mut batch)?;
        batch.into_inner().commit()?;
        Ok(result)
    }
}

