//! [`TableSchemaBuilder`](super::TableSchemaBuilder) and identifier validation.
use super::*;

/// Longest table or column name accepted by [`TableSchemaBuilder::build`],
/// chosen so a derived index table name (`<table>__idx_<column>`) always
/// fits the storage layer's 255-byte table-name limit.
pub const MAX_IDENTIFIER_LEN: usize = 100;

pub(super) fn check_identifier(what: &str, name: &str) -> Result<(), String> {
    if name.is_empty() || name.len() > MAX_IDENTIFIER_LEN {
        return Err(format!("{what} name must be 1..={MAX_IDENTIFIER_LEN} bytes, got '{name}'"));
    }
    if !name.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_') {
        return Err(format!("{what} name '{name}' may only contain ASCII letters, digits and '_'"));
    }
    if name.contains("__") {
        // Reserves `__` for derived physical names like `<t>__idx_<c>`, so a
        // user table can never alias another table's index.
        return Err(format!("{what} name '{name}' may not contain '__'"));
    }
    Ok(())
}

/// Builder for a validated [`TableSchema`].
#[derive(Debug, Clone)]
pub struct TableSchemaBuilder {
    pub(super) name: String,
    pub(super) columns: Vec<ColumnSchema>,
    pub(super) primary_key: Option<String>,
    pub(super) auto_increment_pk: bool,
    pub(super) indexed_columns: Vec<String>,
}

impl TableSchemaBuilder {
    /// Adds a column, replacing any existing column with the same name.
    pub fn column(mut self, column: ColumnSchema) -> Self {
        self.columns.retain(|c| c.name != column.name);
        self.columns.push(column);
        self
    }

    pub fn drop_column(mut self, name: &str) -> Self {
        self.columns.retain(|c| c.name != name);
        self.indexed_columns.retain(|c| c != name);
        self
    }

    pub fn primary_key(mut self, column: impl Into<String>) -> Self {
        self.primary_key = Some(column.into());
        self
    }

    pub fn auto_increment(mut self) -> Self {
        self.auto_increment_pk = true;
        self
    }

    pub fn index(mut self, column: impl Into<String>) -> Self {
        let column = column.into();
        if !self.indexed_columns.contains(&column) {
            self.indexed_columns.push(column);
        }
        self
    }

    pub fn drop_index(mut self, column: &str) -> Self {
        self.indexed_columns.retain(|c| c != column);
        for c in &mut self.columns {
            if c.name == column {
                c.unique = false;
            }
        }
        self
    }

    pub fn build(self) -> Result<TableSchema, BknError> {
        let table = self.name.clone();
        let err = |message: String| BknError::SchemaMismatch { table: table.clone(), message };

        check_identifier("table", &self.name).map_err(err)?;
        if crate::is_reserved(&self.name) {
            return Err(BknError::ReservedTableName(self.name));
        }
        let mut seen = std::collections::HashSet::new();
        for c in &self.columns {
            check_identifier("column", &c.name).map_err(err)?;
            if !seen.insert(c.name.as_str()) {
                return Err(err(format!("duplicate column '{}'", c.name)));
            }
            if c.kind == ColumnKind::Null {
                return Err(err(format!("column '{}' cannot have kind Null", c.name)));
            }
            if c.unique && !c.kind.is_keyable() {
                return Err(err(format!("UNIQUE column '{}' must be Int or Str, got {:?}", c.name, c.kind)));
            }
            match &c.default {
                Some(PropValue::Null) if !c.nullable => {
                    return Err(err(format!("NOT NULL column '{}' cannot default to null", c.name)));
                }
                Some(v) if !matches!(v, PropValue::Null) && ColumnKind::of(v) != c.kind => {
                    return Err(err(format!("default for column '{}' must be {:?}, got {:?}", c.name, c.kind, ColumnKind::of(v))));
                }
                _ => {}
            }
        }

        let pk = self.primary_key.ok_or_else(|| err("no primary key declared".to_string()))?;
        let mut columns = self.columns;
        let pk_col = columns
            .iter_mut()
            .find(|c| c.name == pk)
            .ok_or_else(|| err(format!("primary key '{pk}' is not a declared column")))?;
        if !pk_col.kind.is_keyable() {
            return Err(err(format!("primary key '{pk}' must be Int or Str, got {:?}", pk_col.kind)));
        }
        if self.auto_increment_pk && pk_col.kind != ColumnKind::Int {
            return Err(err(format!("auto-increment primary key '{pk}' must be Int")));
        }
        // The pk is inherently unique and non-null, and lives in the row key
        // rather than an index.
        pk_col.nullable = false;
        pk_col.unique = false;
        pk_col.default = None;

        let mut indexed: Vec<String> = Vec::new();
        for name in self.indexed_columns.iter().chain(columns.iter().filter(|c| c.unique).map(|c| &c.name)) {
            if *name == pk || indexed.contains(name) {
                continue;
            }
            let col = columns
                .iter()
                .find(|c| &c.name == name)
                .ok_or_else(|| err(format!("indexed column '{name}' is not a declared column")))?;
            if !col.kind.is_keyable() {
                return Err(err(format!("indexed column '{name}' must be Int or Str, got {:?}", col.kind)));
            }
            indexed.push(name.clone());
        }

        Ok(TableSchema::from_def(TableDef {
            name: self.name,
            columns,
            primary_key: pk,
            auto_increment_pk: self.auto_increment_pk,
            indexed_columns: indexed,
        }))
    }
}

use std::sync::Arc;

use crate::value::PropValue;
use crate::{BknError, TableSpec};

mod builder;
#[cfg(test)]
mod tests;

pub use builder::*;

/// Column value kind. Mirrors `crate::value::PropValue`'s variants 1:1 —
/// declared separately (rather than reusing `PropValue` itself as the type
/// tag) because a schema needs to name a *kind* independent of any concrete
/// value, e.g. to validate an inserted row's columns against the schema.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, serde::Serialize, serde::Deserialize)]
pub enum ColumnKind {
    Null,
    Bool,
    Int,
    Float,
    Str,
    Bytes,
    // Appended (catalog entries are serialized by variant index).
    Timestamp,
    Uuid,
    List,
    Map,
}

impl ColumnKind {
    /// The kind of a concrete value.
    pub fn of(value: &PropValue) -> ColumnKind {
        match value {
            PropValue::Null => ColumnKind::Null,
            PropValue::Bool(_) => ColumnKind::Bool,
            PropValue::Int(_) => ColumnKind::Int,
            PropValue::Float(_) => ColumnKind::Float,
            PropValue::Str(_) => ColumnKind::Str,
            PropValue::Bytes(_) => ColumnKind::Bytes,
            PropValue::Timestamp(_) => ColumnKind::Timestamp,
            PropValue::Uuid(_) => ColumnKind::Uuid,
            PropValue::List(_) => ColumnKind::List,
            PropValue::Map(_) => ColumnKind::Map,
        }
    }

    /// Whether values of this kind can be a primary key or be indexed
    /// (only these have a sortable byte encoding).
    pub fn is_keyable(self) -> bool {
        matches!(self, ColumnKind::Int | ColumnKind::Str | ColumnKind::Timestamp | ColumnKind::Uuid)
    }
}

#[derive(Debug, Clone, Copy)]
pub struct ColumnDef {
    pub name: &'static str,
    pub kind: ColumnKind,
}

/// Compile-time schema for a relational table, written as a `static`:
///
/// ```ignore
/// static USERS: RelSchema = RelSchema { name: "users", columns: &[..], .. };
/// ```
///
/// Every API that takes a schema accepts `&RelSchema` and converts it into a
/// [`TableSchema`], the owned runtime form that additionally supports
/// constraints (NOT NULL, UNIQUE, DEFAULT) and can be stored in the catalog.
/// A `RelSchema`'s columns are all nullable, non-unique and default-less.
#[derive(Debug, Clone, Copy)]
pub struct RelSchema {
    pub name: &'static str,
    pub columns: &'static [ColumnDef],
    pub primary_key: &'static str,
    pub auto_increment_pk: bool,
    pub indexed_columns: &'static [&'static str],
}

impl RelSchema {
    pub fn column(&self, name: &str) -> Option<&'static ColumnDef> {
        self.columns.iter().find(|c| c.name == name)
    }

    pub fn primary_key_column(&self) -> &'static ColumnDef {
        self.column(self.primary_key)
            .expect("RelSchema.primary_key must name one of RelSchema.columns")
    }

    pub fn is_indexed(&self, column: &str) -> bool {
        self.indexed_columns.contains(&column)
    }
}

/// Anything that can tell a [`crate::relational::Row`] which column is its
/// primary key — implemented by both schema forms so `Row::get` accepts
/// either.
pub trait HasPrimaryKey {
    fn primary_key_name(&self) -> &str;
}

impl HasPrimaryKey for RelSchema {
    fn primary_key_name(&self) -> &str {
        self.primary_key
    }
}

impl HasPrimaryKey for TableSchema {
    fn primary_key_name(&self) -> &str {
        self.primary_key()
    }
}

/// One column of a [`TableSchema`], with its constraints.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct ColumnSchema {
    pub name: String,
    pub kind: ColumnKind,
    /// `false` = NOT NULL: the column must be present with a non-null value.
    pub nullable: bool,
    /// UNIQUE: no two rows may share a non-null value. Implies an index.
    pub unique: bool,
    /// Filled in on insert/upsert when the column is absent.
    pub default: Option<PropValue>,
}

impl ColumnSchema {
    /// A nullable, non-unique column with no default.
    pub fn new(name: impl Into<String>, kind: ColumnKind) -> Self {
        Self {
            name: name.into(),
            kind,
            nullable: true,
            unique: false,
            default: None,
        }
    }

    pub fn not_null(mut self) -> Self {
        self.nullable = false;
        self
    }

    pub fn unique(mut self) -> Self {
        self.unique = true;
        self
    }

    pub fn default_value(mut self, value: impl Into<PropValue>) -> Self {
        self.default = Some(value.into());
        self
    }
}

/// The serialized, catalog-stored part of a [`TableSchema`].
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub(crate) struct TableDef {
    pub name: String,
    pub columns: Vec<ColumnSchema>,
    pub primary_key: String,
    pub auto_increment_pk: bool,
    /// Every secondary-indexed column, including UNIQUE ones; never the pk.
    pub indexed_columns: Vec<String>,
}

/// Owned runtime schema for a relational table: built with
/// [`TableSchema::builder`], loaded from the catalog, or converted from a
/// static [`RelSchema`]. Cloning is cheap (one `Arc` bump).
#[derive(Clone)]
pub struct TableSchema {
    def: Arc<TableDef>,
    base: TableSpec,
}

impl std::fmt::Debug for TableSchema {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.def.fmt(f)
    }
}

impl PartialEq for TableSchema {
    fn eq(&self, other: &Self) -> bool {
        self.def == other.def
    }
}

impl TableSchema {
    pub fn builder(name: impl Into<String>) -> TableSchemaBuilder {
        TableSchemaBuilder {
            name: name.into(),
            columns: Vec::new(),
            primary_key: None,
            auto_increment_pk: false,
            indexed_columns: Vec::new(),
        }
    }

    /// Starts a builder pre-filled with this schema — the way to derive a
    /// modified schema (e.g. with one more column) for
    /// [`crate::relational::RelationalDb::ensure_table`].
    pub fn to_builder(&self) -> TableSchemaBuilder {
        TableSchemaBuilder {
            name: self.def.name.clone(),
            columns: self.def.columns.clone(),
            primary_key: Some(self.def.primary_key.clone()),
            auto_increment_pk: self.def.auto_increment_pk,
            indexed_columns: self.def.indexed_columns.clone(),
        }
    }

    pub(crate) fn from_def(def: TableDef) -> Self {
        let base = TableSpec(crate::relational::codec::intern(&def.name));
        Self { def: Arc::new(def), base }
    }

    pub(crate) fn def(&self) -> &TableDef {
        &self.def
    }

    pub fn name(&self) -> &str {
        &self.def.name
    }

    pub fn columns(&self) -> &[ColumnSchema] {
        &self.def.columns
    }

    pub fn column(&self, name: &str) -> Option<&ColumnSchema> {
        self.def.columns.iter().find(|c| c.name == name)
    }

    pub fn primary_key(&self) -> &str {
        &self.def.primary_key
    }

    pub fn primary_key_column(&self) -> &ColumnSchema {
        self.column(&self.def.primary_key)
            .expect("TableSchema.primary_key must name one of its columns")
    }

    pub fn auto_increment_pk(&self) -> bool {
        self.def.auto_increment_pk
    }

    pub fn indexed_columns(&self) -> &[String] {
        &self.def.indexed_columns
    }

    pub fn is_indexed(&self, column: &str) -> bool {
        self.def.indexed_columns.iter().any(|c| c == column)
    }

    /// The physical KV table holding this table's rows.
    pub(crate) fn base_table(&self) -> TableSpec {
        self.base
    }
}

impl From<&RelSchema> for TableSchema {
    fn from(s: &RelSchema) -> Self {
        let def = TableDef {
            name: s.name.to_string(),
            columns: s.columns.iter().map(|c| ColumnSchema::new(c.name, c.kind)).collect(),
            primary_key: s.primary_key.to_string(),
            auto_increment_pk: s.auto_increment_pk,
            indexed_columns: s.indexed_columns.iter().map(|c| c.to_string()).collect(),
        };
        // `s.name` is already `'static`: no interning needed.
        Self {
            def: Arc::new(def),
            base: TableSpec(s.name),
        }
    }
}

impl From<&TableSchema> for TableSchema {
    fn from(s: &TableSchema) -> Self {
        s.clone()
    }
}

use super::*;

fn users() -> TableSchemaBuilder {
    TableSchema::builder("users")
        .column(ColumnSchema::new("id", ColumnKind::Int))
        .column(ColumnSchema::new("email", ColumnKind::Str).not_null().unique())
        .column(ColumnSchema::new("age", ColumnKind::Int).default_value(0))
        .primary_key("id")
        .auto_increment()
}

#[test]
fn builder_indexes_unique_columns_and_normalizes_the_pk() {
    let s = users().index("id").build().unwrap();
    assert_eq!(s.indexed_columns(), &["email".to_string()]);
    assert!(!s.primary_key_column().nullable);
    assert_eq!(s.base_table().0, "users");
}

#[test]
fn builder_rejects_invalid_definitions() {
    assert!(TableSchema::builder("bad name").column(ColumnSchema::new("id", ColumnKind::Int)).primary_key("id").build().is_err());
    assert!(TableSchema::builder("a__b").column(ColumnSchema::new("id", ColumnKind::Int)).primary_key("id").build().is_err());
    assert!(matches!(
        TableSchema::builder("meta").column(ColumnSchema::new("id", ColumnKind::Int)).primary_key("id").build(),
        Err(BknError::ReservedTableName(_))
    ));
    assert!(users().primary_key("nope").build().is_err());
    assert!(users().index("missing").build().is_err());
    assert!(users().column(ColumnSchema::new("f", ColumnKind::Float)).index("f").build().is_err());
    assert!(users().column(ColumnSchema::new("n", ColumnKind::Int).default_value("x")).build().is_err());
    assert!(TableSchema::builder("t")
        .column(ColumnSchema::new("id", ColumnKind::Str))
        .primary_key("id")
        .auto_increment()
        .build()
        .is_err());
}

#[test]
fn static_schema_converts_losslessly() {
    static S: RelSchema = RelSchema {
        name: "files",
        columns: &[ColumnDef { name: "id", kind: ColumnKind::Int }, ColumnDef { name: "path", kind: ColumnKind::Str }],
        primary_key: "id",
        auto_increment_pk: true,
        indexed_columns: &["path"],
    };
    let t = TableSchema::from(&S);
    assert_eq!(t.name(), "files");
    assert!(t.is_indexed("path"));
    assert!(t.column("path").unwrap().nullable);
    assert_eq!(t.base_table().0, "files");
}

crates/bkndb-core/src/relational/search/:
//! Full-text indexing (tokenizer, postings, maintenance) and BM25 search.
use super::*;

// ---------------------------------------------------------------------------
// Storage layout
// ---------------------------------------------------------------------------

pub(super) fn registry_key(table: &str) -> Vec<u8> {
    format!("relfts:{table}").into_bytes()
}

pub(super) fn stats_key(table: &str, column: &str) -> Vec<u8> {
    format!("relftsstat:{table}:{column}").into_bytes()
}

pub(super) fn postings_table(table: &str, column: &str) -> TableSpec {
    TableSpec(intern(&format!("{table}__fts_{column}")))
}

pub(super) fn docs_table(table: &str, column: &str) -> TableSpec {
    TableSpec(intern(&format!("{table}__ftsdoc_{column}")))
}

pub(super) fn enc_err(e: impl std::fmt::Display) -> BknError {
    BknError::Encoding(e.to_string())
}

/// Columns of `table` that have a full-text index.
pub(crate) fn fulltext_columns_in<R: StorageReadTx>(rtx: &R, table: &str) -> Result<Vec<String>, BknError> {
    match rtx.get(meta_table(), &registry_key(table))? {
        Some(bytes) => bincode::deserialize(&bytes).map_err(enc_err),
        None => Ok(Vec::new()),
    }
}

pub(super) fn save_columns<W: StorageWriteTx>(wtx: &mut W, table: &str, columns: &[String]) -> Result<(), BknError> {
    if columns.is_empty() {
        wtx.delete(meta_table(), &registry_key(table))
    } else {
        wtx.put(meta_table(), &registry_key(table), &bincode::serialize(columns).map_err(enc_err)?)
    }
}

/// `(documents, total terms)` indexed for one column.
pub(super) fn load_stats<R: StorageReadTx>(rtx: &R, table: &str, column: &str) -> Result<(u64, u64), BknError> {
    match rtx.get(meta_table(), &stats_key(table, column))? {
        Some(b) if b.len() == 16 => Ok((u64::from_be_bytes(b[..8].try_into().unwrap()), u64::from_be_bytes(b[8..].try_into().unwrap()))),
        Some(_) => Err(BknError::Corruption(format!("full-text statistics for '{table}.{column}' are malformed"))),
        None => Ok((0, 0)),
    }
}

pub(super) fn save_stats<W: StorageWriteTx>(wtx: &mut W, table: &str, column: &str, docs: u64, terms: u64) -> Result<(), BknError> {
    let mut b = docs.to_be_bytes().to_vec();
    b.extend_from_slice(&terms.to_be_bytes());
    wtx.put(meta_table(), &stats_key(table, column), &b)
}

// ---------------------------------------------------------------------------
// Tokenizing and index maintenance
// ---------------------------------------------------------------------------

/// Splits text into lowercase runs of Unicode letters/digits.
pub fn tokenize(text: &str) -> Vec<String> {
    text.split(|c: char| !c.is_alphanumeric()).filter(|t| !t.is_empty()).map(str::to_lowercase).collect()
}

pub(super) fn postings_key(term: &str, pk: &[u8]) -> Vec<u8> {
    let mut k = Vec::with_capacity(term.len() + 1 + pk.len());
    k.extend_from_slice(term.as_bytes());
    k.push(0);
    k.extend_from_slice(pk);
    k
}

pub(super) fn text_of<'p>(values: Option<&'p Properties>, column: &str) -> Option<&'p str> {
    match values?.get(column)? {
        PropValue::Str(s) => Some(s),
        _ => None,
    }
}

pub(super) fn index_text<W: StorageWriteTx>(wtx: &mut W, table: &str, column: &str, pk: &[u8], text: &str, sign: i64) -> Result<(), BknError> {
    let tokens = tokenize(text);
    let mut tf: BTreeMap<&str, u32> = BTreeMap::new();
    for t in &tokens {
        *tf.entry(t).or_default() += 1;
    }
    let postings = postings_table(table, column);
    for (term, n) in &tf {
        if sign > 0 {
            wtx.put(postings, &postings_key(term, pk), &n.to_be_bytes())?;
        } else {
            wtx.delete(postings, &postings_key(term, pk))?;
        }
    }
    if sign > 0 {
        wtx.put(docs_table(table, column), pk, &(tokens.len() as u32).to_be_bytes())?;
    } else {
        wtx.delete(docs_table(table, column), pk)?;
    }
    let (docs, terms) = load_stats(&*wtx, table, column)?;
    let len = tokens.len() as u64;
    let (docs, terms) = if sign > 0 { (docs + 1, terms + len) } else { (docs.saturating_sub(1), terms.saturating_sub(len)) };
    save_stats(wtx, table, column, docs, terms)
}

/// Keeps every full-text and vector index of `schema`'s table in step with
/// one row change (`old`/`new` are the row's non-pk values before/after;
/// `None` = absent). Called by every relational write path.
pub(crate) fn on_row_change<W: StorageWriteTx>(
    wtx: &mut W,
    schema: &TableSchema,
    pk: &PropValue,
    old: Option<&Properties>,
    new: Option<&Properties>,
) -> Result<(), BknError> {
    let columns = fulltext_columns_in(&*wtx, schema.name())?;
    let has_ann = !ann::columns_in(&*wtx, schema.name())?.is_empty();
    if columns.is_empty() && !has_ann {
        return Ok(());
    }
    let pk = sortable_encode(pk)?;
    if has_ann {
        ann::on_row_change(wtx, schema, &pk, old, new)?;
    }
    for column in &columns {
        let (before, after) = (text_of(old, column), text_of(new, column));
        if before == after {
            continue;
        }
        if let Some(t) = before {
            index_text(wtx, schema.name(), column, &pk, t, -1)?;
        }
        if let Some(t) = after {
            index_text(wtx, schema.name(), column, &pk, t, 1)?;
        }
    }
    Ok(())
}

pub(crate) fn clear<W: StorageWriteTx>(wtx: &mut W, table: TableSpec) -> Result<(), BknError> {
    for (k, _) in wtx.range(table, Bound::Unbounded, Bound::Unbounded)? {
        wtx.delete(table, &k)?;
    }
    Ok(())
}

pub(super) fn drop_index_data<W: StorageWriteTx>(wtx: &mut W, table: &str, column: &str) -> Result<(), BknError> {
    clear(wtx, postings_table(table, column))?;
    clear(wtx, docs_table(table, column))?;
    wtx.delete(meta_table(), &stats_key(table, column))
}

/// Drops the full-text and vector indexes of columns `schema` no longer has
/// (after a migration), or of every column (`schema = None`, table dropped).
pub(crate) fn retain_valid_in<W: StorageWriteTx>(wtx: &mut W, table: &str, schema: Option<&TableSchema>) -> Result<(), BknError> {
    ann::retain_valid_in(wtx, table, schema)?;
    let columns = fulltext_columns_in(&*wtx, table)?;
    let (keep, gone): (Vec<String>, Vec<String>) = columns
        .into_iter()
        .partition(|c| schema.is_some_and(|s| s.column(c).is_some_and(|col| col.kind == ColumnKind::Str)));
    if gone.is_empty() {
        return Ok(());
    }
    for c in &gone {
        drop_index_data(wtx, table, c)?;
    }
    save_columns(wtx, table, &keep)
}

pub(crate) fn create_fulltext_index_in<W: StorageWriteTx>(wtx: &mut W, table: &str, column: &str) -> Result<bool, BknError> {
    let schema = catalog::require_schema_in(&*wtx, table)?;
    match schema.column(column) {
        Some(c) if c.kind == ColumnKind::Str && column != schema.primary_key() => {}
        Some(_) => {
            return Err(BknError::SchemaMismatch {
                table: table.to_string(),
                message: format!("full-text indexes need a non-key Str column; '{column}' isn't one"),
            });
        }
        None => {
            return Err(BknError::SchemaMismatch { table: table.to_string(), message: format!("unknown column '{column}'") });
        }
    }
    let mut columns = fulltext_columns_in(&*wtx, table)?;
    if columns.iter().any(|c| c == column) {
        return Ok(false);
    }
    // Start from a clean slate, then backfill.
    drop_index_data(wtx, table, column)?;
    columns.push(column.to_string());
    save_columns(wtx, table, &columns)?;
    for row in scan_all_in(&*wtx, &schema)? {
        if let Some(text) = text_of(Some(&row.values), column) {
            let text = text.to_string();
            index_text(wtx, table, column, &sortable_encode(&row.pk)?, &text, 1)?;
        }
    }
    Ok(true)
}

pub(crate) fn drop_fulltext_index_in<W: StorageWriteTx>(wtx: &mut W, table: &str, column: &str) -> Result<bool, BknError> {
    let mut columns = fulltext_columns_in(&*wtx, table)?;
    let Some(pos) = columns.iter().position(|c| c == column) else {
        return Ok(false);
    };
    columns.remove(pos);
    drop_index_data(wtx, table, column)?;
    save_columns(wtx, table, &columns)?;
    Ok(true)
}

pub(super) const BM25_K1: f64 = 1.2;
pub(super) const BM25_B: f64 = 0.75;

/// BM25-ranked rows whose `column` matches `query`.
///
/// Every query word adds to the score of the rows containing it; with
/// `match_all`, only rows containing every word qualify. `word*` matches any
/// term starting with `word`. `filter` further restricts the rows.
pub(crate) fn search_text_in<R: StorageReadTx>(
    rtx: &R,
    schema: &TableSchema,
    column: &str,
    query: &str,
    limit: usize,
    match_all: bool,
    filter: Option<&Expr>,
) -> Result<Vec<ScoredRow>, BknError> {
    let table = schema.name();
    if !fulltext_columns_in(rtx, table)?.iter().any(|c| c == column) {
        return Err(BknError::InvalidQuery(format!("'{table}.{column}' has no full-text index (create one first)")));
    }
    let filter = validated_filter(schema, filter)?;
    // Query terms, each (text, is_prefix). A `*` applies to the word's last token.
    let mut terms: Vec<(String, bool)> = Vec::new();
    for word in query.split_whitespace() {
        let prefix = word.ends_with('*');
        let tokens = tokenize(word.trim_end_matches('*'));
        let n = tokens.len();
        for (i, t) in tokens.into_iter().enumerate() {
            let entry = (t, prefix && i + 1 == n);
            if !terms.contains(&entry) {
                terms.push(entry);
            }
        }
    }
    if terms.is_empty() || limit == 0 {
        return Ok(Vec::new());
    }

    let (docs, total) = load_stats(rtx, table, column)?;
    let avgdl = if docs == 0 { 1.0 } else { (total as f64 / docs as f64).max(1.0) };
    let postings = postings_table(table, column);
    let doc_lens = docs_table(table, column);
    let mut lens: HashMap<Vec<u8>, f64> = HashMap::new();
    // pk bytes -> (score, bitmask of query terms matched)
    let mut hits: HashMap<Vec<u8>, (f64, u64)> = HashMap::new();
    for (i, (term, prefix)) in terms.iter().enumerate() {
        let lo = if *prefix { term.as_bytes().to_vec() } else { postings_key(term, &[]) };
        let mut hi = lo.clone();
        // Exclusive upper bound: everything starting with `lo`.
        while let Some(last) = hi.pop() {
            if last < 0xFF {
                hi.push(last + 1);
                break;
            }
        }
        let hi_bound = if hi.is_empty() { Bound::Unbounded } else { Bound::Excluded(hi.as_slice()) };
        // Group postings by exact term (a prefix may expand to many terms).
        let mut by_term: BTreeMap<Vec<u8>, Vec<(Vec<u8>, u32)>> = BTreeMap::new();
        for kv in rtx.scan(postings, Bound::Included(lo.as_slice()), hi_bound)? {
            let (k, v) = kv?;
            let split = k.iter().position(|&b| b == 0).ok_or_else(|| BknError::Corruption("malformed full-text posting".into()))?;
            let tf = u32::from_be_bytes(v.as_slice().try_into().map_err(|_| BknError::Corruption("malformed term frequency".into()))?);
            by_term.entry(k[..split].to_vec()).or_default().push((k[split + 1..].to_vec(), tf));
        }
        for list in by_term.into_values() {
            let df = list.len() as f64;
            let idf = (1.0 + (docs as f64 - df + 0.5) / (df + 0.5)).ln();
            for (pk, tf) in list {
                let dl = match lens.get(&pk) {
                    Some(l) => *l,
                    None => {
                        let l = rtx.get(doc_lens, &pk)?.and_then(|b| b.try_into().ok()).map_or(avgdl, |b: [u8; 4]| u32::from_be_bytes(b) as f64);
                        lens.insert(pk.clone(), l);
                        l
                    }
                };
                let tf = tf as f64;
                let s = idf * tf * (BM25_K1 + 1.0) / (tf + BM25_K1 * (1.0 - BM25_B + BM25_B * dl / avgdl));
                let e = hits.entry(pk).or_insert((0.0, 0));
                e.0 += s;
                e.1 |= 1u64 << (i.min(63));
            }
        }
    }
    let all_mask = if terms.len() >= 64 { u64::MAX } else { (1u64 << terms.len()) - 1 };
    let mut ranked: Vec<(Vec<u8>, f64)> =
        hits.into_iter().filter(|(_, (_, mask))| !match_all || *mask == all_mask).map(|(pk, (s, _))| (pk, s)).collect();
    ranked.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    let pk_kind = schema.primary_key_column().kind;
    let mut out = Vec::new();
    for (pk, score) in ranked {
        let Some(row) = get_in(rtx, schema, &decode_sortable(pk_kind, &pk)?)? else { continue };
        if filter.as_ref().is_some_and(|q| !q.filters.iter().all(|f| f.eval(schema, &row))) {
            continue;
        }
        out.push(ScoredRow { row, score });
        if out.len() >= limit {
            break;
        }
    }
    Ok(out)
}

//! Full-text and vector search over relational tables (the `search`
//! feature).
//!
//! **Full-text.** [`RelationalDb::create_fulltext_index`] builds an inverted
//! index over a `Str` column, kept up to date by every insert, update and
//! delete from then on (in the same transaction). Text is split into
//! lowercase runs of Unicode letters and digits — no stemming or stop words,
//! so it's language-neutral. [`RelationalDb::search_text`] ranks rows with
//! BM25; a query word ending in `*` matches as a prefix.
//!
//! Storage: `<table>__fts_<column>` holds postings
//! `term ++ 0x00 ++ sortable(pk)` → term frequency, `<table>__ftsdoc_<column>`
//! holds `sortable(pk)` → document length, and the shared `meta` table holds
//! the registry (`relfts:<table>`) and corpus totals
//! (`relftsstat:<table>:<column>`).
//!
//! **Vectors.** [`RelationalDb::search_vector`] is exact k-nearest-neighbour
//! search over a column holding embeddings — either a `List` of numbers, or
//! `Bytes` of packed little-endian `f32`s (4 bytes per dimension, far more
//! compact). Without an index it streams the table (or only the rows an
//! optional filter selects, using the query planner) keeping the best
//! `limit` in a heap: exact, linear time, fine up to a few hundred thousand
//! rows. [`RelationalDb::create_vector_index`] adds an approximate HNSW index
//! (see [`crate::relational::ann`]) that searches with the same metric then
//! use automatically.
use std::cmp::Ordering;
use std::collections::{BTreeMap, BinaryHeap, HashMap};
use std::ops::Bound;

use crate::relational::ann::{self, VectorIndexInfo, VectorIndexOptions, VectorSearchOptions};
use crate::relational::catalog;
use crate::relational::codec::{decode_sortable, intern, meta_table, sortable_encode};
