use super::*;

fn leaf(op: FfiExprOp, col: &str, v: i64) -> FfiExprNode {
    FfiExprNode { op, column: Some(col.into()), values: vec![FfiPropValue::Int(v)], children: vec![] }
}

#[test]
fn post_order_nodes_build_the_expected_tree() {
    let nodes = vec![
        leaf(FfiExprOp::Ge, "a", 1),
        leaf(FfiExprOp::Lt, "a", 5),
        FfiExprNode { op: FfiExprOp::And, column: None, values: vec![], children: vec![0, 1] },
        FfiExprNode { op: FfiExprOp::Not, column: None, values: vec![], children: vec![2] },
    ];
    let e = build_expr(nodes).unwrap().unwrap();
    assert_eq!(
        e,
        Expr::Not(Box::new(Expr::And(vec![
            Expr::Cmp("a".into(), CmpOp::Ge, 1.into()),
            Expr::Cmp("a".into(), CmpOp::Lt, 5.into()),
        ])))
    );
}

#[test]
fn malformed_trees_are_rejected() {
    let and_self = FfiExprNode { op: FfiExprOp::And, column: None, values: vec![], children: vec![0] };
    assert!(build_expr(vec![and_self]).is_err(), "forward/self reference");
    assert!(build_expr(vec![leaf(FfiExprOp::Eq, "a", 1), leaf(FfiExprOp::Eq, "b", 2)]).is_err(), "dangling node");
    let twice = FfiExprNode { op: FfiExprOp::Or, column: None, values: vec![], children: vec![0, 0] };
    assert!(build_expr(vec![leaf(FfiExprOp::Eq, "a", 1), twice]).is_err(), "reused node");
    let no_col = FfiExprNode { op: FfiExprOp::Eq, column: None, values: vec![FfiPropValue::Int(1)], children: vec![] };
    assert!(build_expr(vec![no_col]).is_err());
}

crates/bkndb-ffi/src/transaction.rs:
//! Explicit, long-lived write transactions over FFI.
//!
//! A backend write transaction can't be stored in a UniFFI object directly:
//! it borrows the database and (for the LSM engine) holds the writer lock
//! guard, which is `!Send`, while exported objects must be `Send + Sync`.
//! So each transaction runs on its own worker thread that owns the open
//! batch; the exported [`BknDbTransaction`] only holds a channel to it and
//! ships each operation over as a closure. Reads inside the transaction see
//! its own uncommitted writes.
use std::collections::HashMap;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{mpsc, Arc, Mutex};
use std::thread::JoinHandle;

use bkndb::MemoryStorageBackend;
use bkndb::RedbStorageBackend;
use bkndb_core::relational::{Query, TableSchema};
use bkndb_core::{BknError, Db, DbWriteBatch, StorageBackend};

use crate::error::FfiBknError;
use crate::lang::FfiQueryResult;
use crate::ops::{self, FfiProps};
use crate::relational::{FfiQuery, FfiRow, FfiTableSchema};
use crate::types::{FfiDirection, FfiEdgeInput, FfiEdgeRecord, FfiNodeInput, FfiNodeRecord, FfiPropValue, FfiTypedNeighbor};

type Job<B> = Box<dyn for<'a> FnOnce(&mut DbWriteBatch<<B as StorageBackend>::WriteTx<'a>>) + Send>;

enum Cmd<B: StorageBackend> {
    Run(Job<B>),
    Commit(mpsc::SyncSender<Result<(), BknError>>),
    Rollback,
}

/// The worker thread owning one open write batch.
pub(crate) struct Worker<B: StorageBackend> {
    sender: mpsc::Sender<Cmd<B>>,
    thread: Option<JoinHandle<()>>,
}

fn worker_gone() -> FfiBknError {
    FfiBknError::Backend { message: "transaction worker thread exited unexpectedly".to_string() }
}

impl<B: StorageBackend + 'static> Worker<B> {
    /// Spawns the worker and waits until its write transaction is open
    /// (i.e. it holds the writer lock).
    pub(crate) fn start(db: Db<B>) -> Result<Self, FfiBknError> {
        let (sender, commands) = mpsc::channel::<Cmd<B>>();
        let (ready_tx, ready_rx) = mpsc::sync_channel::<Result<(), BknError>>(1);
        let thread = std::thread::Builder::new()
            .name("bkndb-transaction".to_string())
            .spawn(move || {
                let mut batch = match db.begin_write() {
                    Ok(batch) => {
                        let _ = ready_tx.send(Ok(()));
                        batch
                    }
                    Err(e) => {
                        let _ = ready_tx.send(Err(e));
                        return;
                    }
                };
                // Ends (rolling back by dropping `batch`) on Rollback, or when
                // the sender side is dropped without an explicit commit.
                while let Ok(cmd) = commands.recv() {
                    match cmd {
                        Cmd::Run(job) => job(&mut batch),
                        Cmd::Commit(reply) => {
                            let _ = reply.send(batch.commit());
                            return;
                        }
                        Cmd::Rollback => return,
                    }
                }
            })
            .map_err(|e| FfiBknError::Backend { message: format!("cannot start transaction thread: {e}") })?;
        ready_rx.recv().map_err(|_| worker_gone())??;
        Ok(Self { sender, thread: Some(thread) })
    }

    pub(crate) fn run<T: Send + 'static>(
        &self,
        f: impl for<'a> FnOnce(&mut DbWriteBatch<B::WriteTx<'a>>) -> Result<T, BknError> + Send + 'static,
    ) -> Result<T, FfiBknError> {
        let (reply_tx, reply_rx) = mpsc::sync_channel(1);
        self.sender
            .send(Cmd::Run(Box::new(move |batch| {
                let _ = reply_tx.send(f(batch));
            })))
            .map_err(|_| worker_gone())?;
        Ok(reply_rx.recv().map_err(|_| worker_gone())??)
    }

    fn finish(mut self, commit: bool) -> Result<(), FfiBknError> {
        let result = if commit {
            let (reply_tx, reply_rx) = mpsc::sync_channel(1);
            self.sender.send(Cmd::Commit(reply_tx)).map_err(|_| worker_gone())?;
            reply_rx.recv().map_err(|_| worker_gone())?.map_err(Into::into)
        } else {
            let _ = self.sender.send(Cmd::Rollback);
            Ok(())
        };
        if let Some(t) = self.thread.take() {
            let _ = t.join();
        }
        result
    }
}

impl<B: StorageBackend> Drop for Worker<B> {
    fn drop(&mut self) {
        // Rollback if never finished; a closed channel also ends the worker.
        let _ = self.sender.send(Cmd::Rollback);
        if let Some(t) = self.thread.take() {
            let _ = t.join();
        }
    }
}

pub(crate) enum TxWorker {
    Disk(Worker<RedbStorageBackend>),
    Mem(Worker<MemoryStorageBackend>),
}

/// An explicit write transaction. Every operation runs inside it and sees
/// its earlier writes; nothing is visible to others or durable until
/// [`BknDbTransaction::commit`]. If any operation fails, the transaction is
/// aborted: later operations and `commit` fail, and it must be rolled back.
/// Dropping an unfinished transaction rolls it back.
#[derive(uniffi::Object)]
pub struct BknDbTransaction {
    worker: Mutex<Option<TxWorker>>,
    aborted: Mutex<Option<String>>,
    /// Shared with the engine: cleared when this transaction ends.
    engine_tx_open: Arc<AtomicBool>,
}

impl BknDbTransaction {
    pub(crate) fn new(worker: TxWorker, engine_tx_open: Arc<AtomicBool>) -> Self {
        Self { worker: Mutex::new(Some(worker)), aborted: Mutex::new(None), engine_tx_open }
    }

    fn check_usable(&self) -> Result<(), FfiBknError> {
        match self.aborted.lock().unwrap_or_else(|e| e.into_inner()).as_ref() {
            Some(message) => Err(FfiBknError::TransactionAborted { message: message.clone() }),
            None => Ok(()),
        }
    }

    fn note_failure<T>(&self, res: Result<T, FfiBknError>) -> Result<T, FfiBknError> {
        if let Err(e) = &res
            && !matches!(e, FfiBknError::TransactionClosed)
        {
            *self.aborted.lock().unwrap_or_else(|p| p.into_inner()) = Some(e.to_string());
        }
        res
    }

    fn end(&self, commit: bool) -> Result<(), FfiBknError> {
        let worker = self.worker.lock().unwrap_or_else(|e| e.into_inner()).take();
        let Some(worker) = worker else {
            return Err(FfiBknError::TransactionClosed);
        };
        let aborted = self.aborted.lock().unwrap_or_else(|e| e.into_inner()).clone();
        let result = match (commit, aborted) {
            (true, Some(message)) => {
                drop(worker); // roll back
                Err(FfiBknError::TransactionAborted { message })
            }
            (commit, _) => match worker {
                TxWorker::Disk(w) => w.finish(commit),
                TxWorker::Mem(w) => w.finish(commit),
            },
        };
        self.engine_tx_open.store(false, Ordering::SeqCst);
        result
    }
}

impl Drop for BknDbTransaction {
    fn drop(&mut self) {
        let _ = self.end(false);
    }
}

/// Runs `$body` (with the open batch bound to `$b`) inside the transaction.
macro_rules! in_tx {
    ($self:expr, |$b:ident| $body:expr) => {{
        $self.check_usable()?;
        let res = {
            let guard = $self.worker.lock().unwrap_or_else(|e| e.into_inner());
            match guard.as_ref() {
                Some(TxWorker::Disk(w)) => w.run(move |$b| $body),
                Some(TxWorker::Mem(w)) => w.run(move |$b| $body),
                None => Err(FfiBknError::TransactionClosed),
            }
        };
        $self.note_failure(res)
    }};
}

#[uniffi::export]
impl BknDbTransaction {
    /// Makes every write of this transaction durable and visible atomically.
    pub fn commit(&self) -> Result<(), FfiBknError> {
        self.end(true)
    }

    /// Runs one SQL statement inside this transaction (it sees the
    /// transaction's own writes). See `BknDbEngine::sql`.
    #[uniffi::method(default(positional = [], named = None))]
    pub fn sql(
        &self,
        query: String,
        positional: Vec<FfiPropValue>,
        named: Option<HashMap<String, FfiPropValue>>,
    ) -> Result<FfiQueryResult, FfiBknError> {
        let params = crate::lang::params(positional, named);
        Ok(in_tx!(self, |b| b.relational().sql(&query, params))?.into())
    }

    /// Runs a graph `MATCH` query inside this transaction. See
    /// `BknDbEngine::graph_query`.
    #[uniffi::method(default(positional = [], named = None))]
    pub fn graph_query(
        &self,
        query: String,
        positional: Vec<FfiPropValue>,
        named: Option<HashMap<String, FfiPropValue>>,
    ) -> Result<FfiQueryResult, FfiBknError> {
        let params = crate::lang::params(positional, named);
        Ok(in_tx!(self, |b| b.graph().query(&query, params))?.into())
    }

    /// Discards every write of this transaction.
    pub fn rollback(&self) -> Result<(), FfiBknError> {
        match self.end(false) {
            Err(FfiBknError::TransactionClosed) | Ok(()) => Ok(()),
            Err(e) => Err(e),
        }
    }

    /// Whether the transaction is still open (not committed or rolled back).
    pub fn is_active(&self) -> bool {
        self.worker.lock().unwrap_or_else(|e| e.into_inner()).is_some()
    }

    // ---- graph ----

    pub fn create_node(&self, label: String, properties: HashMap<String, FfiPropValue>) -> Result<u64, FfiBknError> {
        in_tx!(self, |b| ops::create_node(b, &label, properties))
    }

    pub fn create_nodes_bulk(&self, nodes: Vec<FfiNodeInput>) -> Result<Vec<u64>, FfiBknError> {
        let nodes: Vec<(String, FfiProps)> = nodes.into_iter().map(|n| (n.label, n.properties)).collect();
        in_tx!(self, |b| ops::create_nodes(b, nodes))
    }

    pub fn create_edge(
        &self,
        from: u64,
        edge_type: String,
        to: u64,
        properties: HashMap<String, FfiPropValue>,
    ) -> Result<u64, FfiBknError> {
        in_tx!(self, |b| ops::create_edge(b, from, &edge_type, to, properties))
    }

    pub fn create_edges_bulk(&self, edges: Vec<FfiEdgeInput>) -> Result<Vec<u64>, FfiBknError> {
        let edges: Vec<_> = edges.into_iter().map(|e| (e.from, e.edge_type, e.to, e.properties)).collect();
        in_tx!(self, |b| ops::create_edges(b, edges))
    }

    pub fn get_node(&self, id: u64) -> Result<Option<FfiNodeRecord>, FfiBknError> {
        in_tx!(self, |b| ops::tx_get_node(b, id))
    }

    pub fn get_edge(&self, id: u64) -> Result<Option<FfiEdgeRecord>, FfiBknError> {
        in_tx!(self, |b| ops::tx_get_edge(b, id))
    }

    pub fn neighbors(&self, node: u64, direction: FfiDirection, edge_type: Option<String>) -> Result<Vec<FfiTypedNeighbor>, FfiBknError> {
        in_tx!(self, |b| ops::tx_neighbors(b, node, direction.into(), edge_type.as_deref()))
    }

    /// Ids of every node with `label` (including ones created in this transaction).
    pub fn nodes_by_label(&self, label: String) -> Result<Vec<u64>, FfiBknError> {
        in_tx!(self, |b| ops::tx_nodes_by_label(b, &label))
    }

    pub fn find_nodes(&self, label: String, property: String, value: FfiPropValue) -> Result<Vec<u64>, FfiBknError> {
        let value: bkndb_core::value::PropValue = value.into();
        in_tx!(self, |b| ops::tx_find_nodes(b, &label, &property, value))
    }

    pub fn delete_node(&self, id: u64) -> Result<(), FfiBknError> {
        in_tx!(self, |b| ops::delete_node(b, id))
    }

    pub fn delete_edge(&self, id: u64) -> Result<bool, FfiBknError> {
        in_tx!(self, |b| ops::delete_edge(b, id))
    }

    pub fn update_node_properties(
        &self,
        id: u64,
        set: HashMap<String, FfiPropValue>,
        unset: Vec<String>,
    ) -> Result<(), FfiBknError> {
        in_tx!(self, |b| ops::update_node(b, id, set, unset))
    }

    pub fn update_edge_properties(
        &self,
        id: u64,
        set: HashMap<String, FfiPropValue>,
        unset: Vec<String>,
    ) -> Result<(), FfiBknError> {
        in_tx!(self, |b| ops::update_edge(b, id, set, unset))
    }

    // ---- relational ----

    pub fn create_table(&self, schema: FfiTableSchema) -> Result<bool, FfiBknError> {
        let schema = self.note_failure(TableSchema::try_from(schema))?;
        in_tx!(self, |b| ops::create_table(b, schema))
    }

    pub fn ensure_table(&self, schema: FfiTableSchema) -> Result<(), FfiBknError> {
        let schema = self.note_failure(TableSchema::try_from(schema))?;
        in_tx!(self, |b| ops::ensure_table(b, schema))
    }

    pub fn drop_table(&self, name: String) -> Result<bool, FfiBknError> {
        in_tx!(self, |b| ops::drop_table(b, &name))
    }

    pub fn insert(&self, table: String, values: HashMap<String, FfiPropValue>) -> Result<FfiPropValue, FfiBknError> {
        in_tx!(self, |b| ops::insert(b, &table, values, false)).map(Into::into)
    }

    pub fn insert_many(&self, table: String, rows: Vec<HashMap<String, FfiPropValue>>) -> Result<Vec<FfiPropValue>, FfiBknError> {
        Ok(in_tx!(self, |b| ops::insert_many(b, &table, rows, false))?.into_iter().map(Into::into).collect())
    }

    pub fn upsert(&self, table: String, values: HashMap<String, FfiPropValue>) -> Result<FfiPropValue, FfiBknError> {
        in_tx!(self, |b| ops::insert(b, &table, values, true)).map(Into::into)
    }

    pub fn upsert_many(&self, table: String, rows: Vec<HashMap<String, FfiPropValue>>) -> Result<Vec<FfiPropValue>, FfiBknError> {
        Ok(in_tx!(self, |b| ops::insert_many(b, &table, rows, true))?.into_iter().map(Into::into).collect())
    }

    pub fn get_row(&self, table: String, pk: FfiPropValue) -> Result<Option<FfiRow>, FfiBknError> {
        in_tx!(self, |b| ops::tx_get_row(b, &table, pk.into()))
    }

    pub fn select(&self, table: String, query: FfiQuery) -> Result<Vec<FfiRow>, FfiBknError> {
        let query = self.note_failure(Query::try_from(query))?;
        in_tx!(self, |b| ops::tx_select(b, &table, &query))
    }

    pub fn count(&self, table: String, query: FfiQuery) -> Result<u64, FfiBknError> {
        let query = self.note_failure(Query::try_from(query))?;
        in_tx!(self, |b| ops::tx_count(b, &table, &query))
    }

    pub fn update_rows(&self, table: String, query: FfiQuery, set: HashMap<String, FfiPropValue>) -> Result<u64, FfiBknError> {
        let query = self.note_failure(Query::try_from(query))?;
        in_tx!(self, |b| ops::update_rows(b, &table, &query, set))
    }

    pub fn delete_rows(&self, table: String, query: FfiQuery) -> Result<u64, FfiBknError> {
        let query = self.note_failure(Query::try_from(query))?;
        in_tx!(self, |b| ops::delete_rows(b, &table, &query))
    }
}

crates/bkndb-ffi/src/types.rs:
use std::collections::HashMap;
use bkndb_core::value::{PropValue, Properties};

#[derive(Debug, Clone, PartialEq, uniffi::Enum)]
pub enum FfiPropValue {
    Null,
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    Bytes(Vec<u8>),
    /// Microseconds since the Unix epoch, UTC.
    Timestamp(i64),
    /// A UUID as two big-endian halves (`hi` = first 8 bytes).
    Uuid { hi: u64, lo: u64 },
    List(Vec<FfiPropValue>),
    Map(HashMap<String, FfiPropValue>),
}

impl From<PropValue> for FfiPropValue {
    fn from(p: PropValue) -> Self {
        match p {
            PropValue::Null => FfiPropValue::Null,
            PropValue::Str(s) => FfiPropValue::Str(s),
            PropValue::Int(i) => FfiPropValue::Int(i),
            PropValue::Float(f) => FfiPropValue::Float(f),
            PropValue::Bool(b) => FfiPropValue::Bool(b),
            PropValue::Bytes(b) => FfiPropValue::Bytes(b),
            PropValue::Timestamp(t) => FfiPropValue::Timestamp(t),
            PropValue::Uuid(u) => FfiPropValue::Uuid {
                hi: u64::from_be_bytes(u[..8].try_into().unwrap()),
                lo: u64::from_be_bytes(u[8..].try_into().unwrap()),
            },
            PropValue::List(l) => FfiPropValue::List(l.into_iter().map(Into::into).collect()),
            PropValue::Map(m) => FfiPropValue::Map(m.into_iter().map(|(k, v)| (k, v.into())).collect()),
        }
    }
}

impl From<FfiPropValue> for PropValue {
    fn from(p: FfiPropValue) -> Self {
        match p {
            FfiPropValue::Null => PropValue::Null,
            FfiPropValue::Str(s) => PropValue::Str(s),
            FfiPropValue::Int(i) => PropValue::Int(i),
            FfiPropValue::Float(f) => PropValue::Float(f),
            FfiPropValue::Bool(b) => PropValue::Bool(b),
            FfiPropValue::Bytes(b) => PropValue::Bytes(b),
            FfiPropValue::Timestamp(t) => PropValue::Timestamp(t),
            FfiPropValue::Uuid { hi, lo } => {
                let mut u = [0u8; 16];
                u[..8].copy_from_slice(&hi.to_be_bytes());
                u[8..].copy_from_slice(&lo.to_be_bytes());
                PropValue::Uuid(u)
            }
            FfiPropValue::List(l) => PropValue::List(l.into_iter().map(Into::into).collect()),
            FfiPropValue::Map(m) => PropValue::Map(m.into_iter().map(|(k, v)| (k, v.into())).collect()),
        }
    }
}

pub fn ffi_props_to_core(props: HashMap<String, FfiPropValue>) -> Properties {
    let mut out = Properties::new();
    for (k, v) in props {
        out.insert(k, v.into());
    }
    out
}

pub fn core_props_to_ffi(props: Properties) -> HashMap<String, FfiPropValue> {
    let mut out = HashMap::new();
    for (k, v) in props {
        out.insert(k, v.into());
    }
    out
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum FfiDirection {
    Out,
    In,
    Both,
}

impl From<FfiDirection> for bkndb_core::graph::Direction {
    fn from(d: FfiDirection) -> Self {
        match d {
            FfiDirection::Out => bkndb_core::graph::Direction::Out,
            FfiDirection::In => bkndb_core::graph::Direction::In,
            FfiDirection::Both => bkndb_core::graph::Direction::Both,
        }
    }
}

#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiNodeRecord {
    pub id: u64,
    pub label: String,
    pub properties: HashMap<String, FfiPropValue>,
}

#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiNodeInput {
    pub label: String,
    pub properties: HashMap<String, FfiPropValue>,
}

#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiEdgeRecord {
    pub id: u64,
    pub from: u64,
    pub to: u64,
    pub edge_type: String,
    pub properties: HashMap<String, FfiPropValue>,
}

#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiEdgeInput {
    pub from: u64,
    pub edge_type: String,
    pub to: u64,
    pub properties: HashMap<String, FfiPropValue>,
}

#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiNeighbor {
    pub node_id: u64,
    pub edge_id: u64,
}

#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiPathStep {
    pub node_id: u64,
    pub via_edge_id: Option<u64>,
    pub edge_type: Option<String>,
}

#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiPathResult {
    pub steps: Vec<FfiPathStep>,
    pub node_ids: Vec<u64>,
    pub edge_ids: Vec<u64>,
}

#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiHubRecord {
    pub node_id: u64,
    pub degree: u64,
}

impl From<bkndb_core::graph::PathResult> for FfiPathResult {
    fn from(p: bkndb_core::graph::PathResult) -> Self {
        FfiPathResult {
            node_ids: p.nodes().into_iter().map(|n| n.0).collect(),
            edge_ids: p.edges().into_iter().map(|e| e.0).collect(),
            steps: p
                .steps
                .into_iter()
                .map(|s| FfiPathStep {
                    node_id: s.node.0,
                    via_edge_id: s.via_edge.map(|e| e.0),
                    edge_type: s.edge_type,
                })
                .collect(),
        }
    }
}

/// Rows to upsert into one registered table as part of a sync batch.
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiTableRows {
    pub table: String,
    pub rows: Vec<HashMap<String, FfiPropValue>>,
}

#[derive(Debug, Clone, Default, PartialEq, uniffi::Record)]
pub struct FfiSyncBatch {
    pub nodes: Vec<FfiNodeInput>,
    pub edges: Vec<FfiEdgeInput>,
    /// Relational rows, upserted by primary key (so a batch can be re-applied).
    #[uniffi(default)]
    pub rows: Vec<FfiTableRows>,
    /// Edges that may connect nodes created by this same batch.
    #[uniffi(default)]
    pub linked_edges: Vec<FfiLinkedEdgeInput>,
}

/// An edge endpoint in a sync batch: an existing node, or the node at
/// `index` (0-based) in the batch's `nodes`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum FfiNodeRef {
    Existing { id: u64 },
    New { index: u32 },
}

impl From<FfiNodeRef> for bkndb_core::NodeRef {
    fn from(r: FfiNodeRef) -> Self {
        match r {
            FfiNodeRef::Existing { id } => bkndb_core::NodeRef::Existing(bkndb_core::graph::NodeId(id)),
            FfiNodeRef::New { index } => bkndb_core::NodeRef::New(index as usize),
        }
    }
}

#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiLinkedEdgeInput {
    pub from: FfiNodeRef,
    pub edge_type: String,
    pub to: FfiNodeRef,
    #[uniffi(default)]
    pub properties: HashMap<String, FfiPropValue>,
}

/// A lowest-cost path and its total cost.
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiWeightedPath {
    pub path: FfiPathResult,
    pub cost: f64,
}

/// An index on `property` of nodes with `label`.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct FfiPropertyIndex {
    pub label: String,
    pub property: String,
}

#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiSyncResult {
    pub node_ids: Vec<u64>,
    pub edge_ids: Vec<u64>,
    /// Primary keys of `FfiSyncBatch::rows`, one list per table entry.
    pub row_pks: Vec<Vec<FfiPropValue>>,
}

/// A neighbor together with the type of the edge leading to it.
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiTypedNeighbor {
    pub node_id: u64,
    pub edge_id: u64,
    pub edge_type: String,
}

/// One node reached by a breadth-first traversal.
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiTraversalHit {
    pub node_id: u64,
    pub depth: u32,
    pub via_edge_id: Option<u64>,
    pub parent_id: Option<u64>,
}

/// Tuning knobs for the on-disk (LSM) engine.
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiLsmOptions {
    /// Flush the in-memory write buffer to disk once it reaches this size.
    pub memtable_flush_bytes: u64,
    /// Compact automatically once this many on-disk segments exist.
    pub compaction_trigger_files: u32,
    /// Target size of one on-disk block (the unit that is checksummed,
    /// compressed and read per lookup). Default 4096.
    #[uniffi(default = None)]
    pub block_size_bytes: Option<u32>,
    /// lz4-compress on-disk blocks. Default true.
    #[uniffi(default = None)]
    pub compression: Option<bool>,
}

/// Row count of one relational table.
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiTableCount {
    pub table: String,
    pub rows: u64,
}

/// File-level figures for an on-disk database (see `LsmStats`).
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiStorageStats {
    pub file_bytes: u64,
    pub sstable_count: u32,
    pub legacy_sstable_count: u32,
    pub sstable_bytes: u64,
    pub sstable_entries: u64,
    pub memtable_entries: u64,
    pub memtable_bytes: u64,
    pub wal_bytes: u64,
    pub reclaimable_bytes: u64,
}

/// Logical counts plus, for on-disk databases, storage figures.
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiDbStats {
    pub nodes: u64,
    pub edges: u64,
    pub tables: Vec<FfiTableCount>,
    /// `None` for in-memory databases.
    pub storage: Option<FfiStorageStats>,
}

/// What `verify_integrity` checked (all zero for in-memory databases).
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct FfiIntegrityReport {
    pub sstables_checked: u32,
    pub blocks_verified: u64,
    pub legacy_blocks_unchecked: u64,
    pub entries: u64,
    pub wal_records: u64,
}

impl From<bkndb::RedbStats> for FfiStorageStats {
    fn from(s: bkndb::RedbStats) -> Self {
        Self {
            file_bytes: s.file_bytes,
            sstable_count: s.table_count as u32,
            legacy_sstable_count: 0,
            sstable_bytes: s.stored_bytes,
            sstable_entries: s.entries,
            memtable_entries: 0,
            memtable_bytes: 0,
            wal_bytes: 0,
            reclaimable_bytes: s.reclaimable_bytes,
        }
    }
}

impl From<bkndb::IntegrityReport> for FfiIntegrityReport {
    fn from(r: bkndb::IntegrityReport) -> Self {
        Self {
            sstables_checked: r.sstables_checked as u32,
            blocks_verified: r.blocks_verified,
            legacy_blocks_unchecked: r.legacy_blocks_unchecked,
            entries: r.entries,
            wal_records: r.wal_records,
        }
    }
}

crates/bkndb-ffi/tests/ffi_graph_indexes:
use std::collections::HashMap;

use bkndb_ffi::{
    BknDbEngine, FfiBknError, FfiDirection, FfiLinkedEdgeInput, FfiNodeInput, FfiNodeRef, FfiPropValue,
    FfiPropertyIndex, FfiSyncBatch,
};

fn props(pairs: &[(&str, FfiPropValue)]) -> HashMap<String, FfiPropValue> {
    pairs.iter().map(|(k, v)| (k.to_string(), v.clone())).collect()
}

#[test]
fn label_and_property_indexes() {
    let db = BknDbEngine::in_memory().unwrap();
    let a = db.create_node("Person".into(), props(&[("age", FfiPropValue::Int(30))])).unwrap();
    let b = db.create_node("Person".into(), props(&[("age", FfiPropValue::Int(40))])).unwrap();
    db.create_node("City".into(), HashMap::new()).unwrap();

    assert_eq!(db.nodes_by_label("Person".into()).unwrap(), vec![a, b]);
    assert_eq!(db.count_nodes("City".into()).unwrap(), 1);
    assert_eq!(db.find_nodes("Person".into(), "age".into(), FfiPropValue::Int(40)).unwrap(), vec![b]);

    assert!(db.create_node_index("Person".into(), "age".into()).unwrap());
    assert_eq!(
        db.list_node_indexes().unwrap(),
        vec![FfiPropertyIndex { label: "Person".into(), property: "age".into() }]
    );
    db.update_node_properties(a, props(&[("age", FfiPropValue::Int(40))]), vec![]).unwrap();
    assert_eq!(db.find_nodes("Person".into(), "age".into(), FfiPropValue::Int(40)).unwrap(), vec![a, b]);

    let tx = db.begin_transaction().unwrap();
    let c = tx.create_node("Person".into(), props(&[("age", FfiPropValue::Int(40))])).unwrap();
    assert_eq!(tx.find_nodes("Person".into(), "age".into(), FfiPropValue::Int(40)).unwrap(), vec![a, b, c]);
    assert_eq!(tx.nodes_by_label("Person".into()).unwrap().len(), 3);
    tx.rollback().unwrap();

    db.rebuild_graph_indexes().unwrap();
    assert!(db.drop_node_index("Person".into(), "age".into()).unwrap());
    assert!(db.list_node_indexes().unwrap().is_empty());
}

#[test]
fn weighted_paths() {
    let db = BknDbEngine::in_memory().unwrap();
    let n: Vec<u64> = (0..3).map(|_| db.create_node("N".into(), HashMap::new()).unwrap()).collect();
    let w = |v: f64| props(&[("km", FfiPropValue::Float(v))]);
    db.create_edge(n[0], "R".into(), n[1], w(1.0)).unwrap();
    db.create_edge(n[1], "R".into(), n[2], w(1.0)).unwrap();
    db.create_edge(n[0], "R".into(), n[2], w(9.0)).unwrap();
    let best = db
        .find_weighted_path(n[0], n[2], FfiDirection::Out, None, "km".into(), 1.0)
        .unwrap()
        .unwrap();
    assert_eq!(best.cost, 2.0);
    assert_eq!(best.path.node_ids, n);
    let bad = db.find_weighted_path(n[0], n[2], FfiDirection::Out, None, "km".into(), -1.0);
    assert!(matches!(bad, Err(FfiBknError::Encoding { .. })));
}

#[test]
fn sync_batch_linked_edges() {
    let db = BknDbEngine::in_memory().unwrap();
    let repo = db.create_node("Repo".into(), HashMap::new()).unwrap();
    let batch = FfiSyncBatch {
        nodes: vec![
            FfiNodeInput { label: "File".into(), properties: HashMap::new() },
            FfiNodeInput { label: "Fn".into(), properties: HashMap::new() },
        ],
        edges: vec![],
        rows: vec![],
        linked_edges: vec![
            FfiLinkedEdgeInput {
                from: FfiNodeRef::Existing { id: repo },
                edge_type: "CONTAINS".into(),
                to: FfiNodeRef::New { index: 0 },
                properties: HashMap::new(),
            },
            FfiLinkedEdgeInput {
                from: FfiNodeRef::New { index: 0 },
                edge_type: "DEFINES".into(),
                to: FfiNodeRef::New { index: 1 },
                properties: HashMap::new(),
            },
        ],
    };
    let res = db.sync_batch(batch.clone()).unwrap();
    assert_eq!(res.edge_ids.len(), 2);
    let hits = db.traverse(repo, FfiDirection::Out, 5, None, None).unwrap();
    assert_eq!(hits.iter().map(|h| h.node_id).collect::<Vec<_>>(), vec![repo, res.node_ids[0], res.node_ids[1]]);

    let mut bad = batch;
    bad.linked_edges[1].to = FfiNodeRef::New { index: 7 };
    assert!(db.sync_batch(bad).is_err());
    assert_eq!(db.count_nodes("File".into()).unwrap(), 1, "failed batch rolled back");
}

crates/bkndb-ffi/tests/ffi_integration.r:
use bkndb_ffi::{
    BknDbEngine, FfiDirection, FfiEdgeInput, FfiNodeInput, FfiPropValue, FfiSyncBatch,
};
use std::collections::HashMap;

#[test]
fn test_in_memory_crud_and_traversal() {
    let engine = BknDbEngine::in_memory().expect("failed to init in-memory engine");

    let mut props1 = HashMap::new();
    props1.insert("name".to_string(), FfiPropValue::Str("Alice".to_string()));
    props1.insert("age".to_string(), FfiPropValue::Int(30));
    props1.insert("active".to_string(), FfiPropValue::Bool(true));

    let n1 = engine.create_node("Person".to_string(), props1).unwrap();

    let mut props2 = HashMap::new();
    props2.insert("name".to_string(), FfiPropValue::Str("Bob".to_string()));
    let n2 = engine.create_node("Person".to_string(), props2).unwrap();

    // Get nodes
    let node1 = engine.get_node(n1).unwrap().expect("node 1 not found");
    assert_eq!(node1.id, n1);
    assert_eq!(node1.label, "Person");
    assert_eq!(
        node1.properties.get("name"),
        Some(&FfiPropValue::Str("Alice".to_string()))
    );
    assert_eq!(node1.properties.get("age"), Some(&FfiPropValue::Int(30)));
    assert_eq!(
        node1.properties.get("active"),
        Some(&FfiPropValue::Bool(true))
    );

    // Create edge
    let mut e_props = HashMap::new();
    e_props.insert("since".to_string(), FfiPropValue::Int(2024));
    let e1 = engine
        .create_edge(n1, "KNOWS".to_string(), n2, e_props)
        .unwrap();

    let edge1 = engine.get_edge(e1).unwrap().expect("edge 1 not found");
    assert_eq!(edge1.id, e1);
    assert_eq!(edge1.from, n1);
    assert_eq!(edge1.to, n2);
    assert_eq!(edge1.edge_type, "KNOWS");
    assert_eq!(
        edge1.properties.get("since"),
        Some(&FfiPropValue::Int(2024))
    );

    // Neighbors
    let out_neighbors = engine.neighbors_out(n1, "KNOWS".to_string()).unwrap();
    assert_eq!(out_neighbors.len(), 1);
    assert_eq!(out_neighbors[0].node_id, n2);
    assert_eq!(out_neighbors[0].edge_id, e1);

    let in_neighbors = engine.neighbors_in(n2, "KNOWS".to_string()).unwrap();
    assert_eq!(in_neighbors.len(), 1);
    assert_eq!(in_neighbors[0].node_id, n1);
    assert_eq!(in_neighbors[0].edge_id, e1);

    // Delete node n2
    engine.delete_node(n2).unwrap();
    assert!(engine.get_node(n2).unwrap().is_none());
    assert!(engine.get_edge(e1).unwrap().is_none());
}

#[test]
fn test_bulk_and_bfs_and_hubs() {
    let engine = BknDbEngine::in_memory().unwrap();

    // Create 5 nodes: A, B, C, D, E
    let nodes = vec![
        FfiNodeInput {
            label: "A".to_string(),
            properties: HashMap::new(),
        },
        FfiNodeInput {
            label: "B".to_string(),
            properties: HashMap::new(),
        },
        FfiNodeInput {
            label: "C".to_string(),
            properties: HashMap::new(),
        },
        FfiNodeInput {
            label: "D".to_string(),
            properties: HashMap::new(),
        },
        FfiNodeInput {
            label: "E".to_string(),
            properties: HashMap::new(),
        },
    ];
    let nids = engine.create_nodes_bulk(nodes).unwrap();
    assert_eq!(nids.len(), 5);

    let (a, b, c, d, e) = (nids[0], nids[1], nids[2], nids[3], nids[4]);

    // Edges:
    // A -> B -> C -> D (3 hops)
    // A -> E -> D      (2 hops)
    let edges = vec![
        FfiEdgeInput {
            from: a,
            edge_type: "CONNECTS".to_string(),
            to: b,
            properties: HashMap::new(),
        },
        FfiEdgeInput {
            from: b,
            edge_type: "CONNECTS".to_string(),
            to: c,
            properties: HashMap::new(),
        },
        FfiEdgeInput {
            from: c,
            edge_type: "CONNECTS".to_string(),
            to: d,
            properties: HashMap::new(),
        },
        FfiEdgeInput {
            from: a,
            edge_type: "SHORTCUT".to_string(),
            to: e,
            properties: HashMap::new(),
        },
        FfiEdgeInput {
            from: e,
            edge_type: "SHORTCUT".to_string(),
            to: d,
            properties: HashMap::new(),
        },
    ];
    let eids = engine.create_edges_bulk(edges).unwrap();
    assert_eq!(eids.len(), 5);

    // Shortest path with all edge types: should take shortcut of length 2
    let path = engine
        .find_shortest_path(a, d, FfiDirection::Out, None)
        .unwrap()
        .expect("path should exist");
    assert_eq!(path.node_ids, vec![a, e, d]);
    assert_eq!(path.steps.len(), 3);
    assert_eq!(path.steps[0].node_id, a);
    assert_eq!(path.steps[1].node_id, e);
    assert_eq!(path.steps[2].node_id, d);

    // Shortest path filtering only CONNECTS: must take 3 hops
    let path_connects = engine
        .find_shortest_path(a, d, FfiDirection::Out, Some(vec!["CONNECTS".to_string()]))
        .unwrap()
        .expect("path should exist");
    assert_eq!(path_connects.node_ids, vec![a, b, c, d]);

    // Top hubs
    let hubs = engine.top_hubs(2, FfiDirection::Both, None).unwrap();
    assert_eq!(hubs.len(), 2);
    // a has 2 outgoing, d has 2 incoming. Degrees should be at least 2.
    assert!(hubs[0].degree >= 2);
}

#[test]
fn test_cascade_delete() {
    let engine = BknDbEngine::in_memory().unwrap();

    let root = engine
        .create_node("Dir".to_string(), HashMap::new())
        .unwrap();
    let sub1 = engine
        .create_node("Dir".to_string(), HashMap::new())
        .unwrap();
    let sub2 = engine
        .create_node("File".to_string(), HashMap::new())
        .unwrap();
    let leaf = engine
        .create_node("File".to_string(), HashMap::new())
        .unwrap();

    engine
        .create_edge(root, "CONTAINS".to_string(), sub1, HashMap::new())
        .unwrap();
    engine
        .create_edge(root, "CONTAINS".to_string(), sub2, HashMap::new())
        .unwrap();
    engine
        .create_edge(sub1, "CONTAINS".to_string(), leaf, HashMap::new())
        .unwrap();

    let deleted = engine.cascade_delete(root, "CONTAINS".to_string()).unwrap();
    assert_eq!(deleted.len(), 4);
    assert!(engine.get_node(root).unwrap().is_none());
    assert!(engine.get_node(sub1).unwrap().is_none());
    assert!(engine.get_node(sub2).unwrap().is_none());
    assert!(engine.get_node(leaf).unwrap().is_none());
}

